def review20_cases():
    """Generate domain/ranking separation and dependency-startup controls."""
    import copy
    previous = review19_cases()
    weights = [
        ("default", "missing", {}),
        ("none", "none", None),
        ("neutral", "set", {}),
        ("reach", "set", {"reach": 2.0}),
        ("impact", "set", {"impact": 0.25}),
        ("confidence", "set", {"confidence": 2.0}),
        ("effort", "set", {"effort": 4.0}),
        ("partial", "set", {"effort": 0.25}),
        ("all", "set", {"reach": 1.5, "impact": 0.5, "confidence": 2.0, "effort": 3.0}),
    ]
    scores = []
    for group, effort, confidence, expected_pool in [
            ("short", 2.0, 1.0, "quick_win"), ("zero", 0.0, 1.0, "quick_win"),
            ("negative", -1.0, 1.0, "quick_win"), ("unknown", None, 1.0, "other"), ("uncertain", 6.0, 0.3, "big_bet")]:
        proposal = copy.deepcopy(previous["proposal"])
        proposal.update(id="synthetic-domain-" + group, title="Synthetic " + group + " task",
                        reach=6.0, impact_label="high", effort_weeks=effort, kano="performance",
                        importance=8.0, satisfaction=2.0)
        if group == "uncertain":
            proposal.update(independent_source_count=0, has_internal_explicit=False,
                            internal_mentions=0, importance=4.0, satisfaction=4.0)
        for name, mode, configured in weights:
            effective = {key: float((configured or {}).get(key, 1.0))
                         for key in ("reach", "impact", "confidence", "effort")}
            denominator = max(0.5, (2.0 if effort is None else effort) * effective["effort"])
            raw = round(6.0 * effective["reach"] * 2.0 * effective["impact"]
                        * confidence * effective["confidence"] / denominator, 6)
            scores.append({"name": group + "-" + name, "proposal": copy.deepcopy(proposal),
                           "weights_mode": mode, "weights": configured, "effective_weights": effective,
                           "domain": {"reach": 6.0, "impact": 2.0, "confidence": confidence, "effort": effort},
                           "pool": expected_pool, "rice_raw": raw,
                           "final_score": round(100.0 * raw / (raw + 6.0), 4)})
    startup = [{"dependency": dependency, "console": console, "log": log}
               for dependency in ("discord", "llmcall") for console in (True, False) for log in (True, False)]
    return {"scores": scores, "startup": startup, "date": "2026-01-15",
            "labels": {"domain": "Domain factors", "weighted": "Weighted RICE"},
            "log_path": previous["private_root"] + "/logs/startup.log",
            "help_args": ["--help"], "invalid_args": ["--mode", "synthetic-invalid"],
            "normal_args": ["--mode", "dry", "--interval", "15", "--display-interval", "30"],
            "missing_message": "No module named",
            "legacy_notice": "Legacy RICE factors", "legacy_provenance": "unweighted",
            "legacy_cases": [{"provenance": provenance, "kano": kano, "pool": pool, "source": source}
                for provenance, kano, pool, source in [(False, "performance", "other", "short-default"),
                    (True, "performance", "quick_win", "short-default"),
                    (False, "performance", "other", "uncertain-default"),
                    (True, "performance", "big_bet", "uncertain-default"),
                    (False, "delighter", "big_bet", "short-default")]],
            "public_api": ["DemandBot", "main", "_llm", "classify_batch"],
            "normal_modes": ["dry", "shadow", "live"]}




def review20_test_source():
    """Generate the synthetic full-module regression suite."""
    return '"""Generated full-module regressions for domain factors and direct CLI bootstrap."""\nimport argparse\nimport builtins\nimport copy\nimport io\nfrom pathlib import Path\nimport types\nimport unittest\n\nfrom test_review19_repairs import Harness, ROOT, SCRIPTS, CASES as OLD_CASES, generator\n\nCASES = generator.review20_cases()\n\n\nclass DomainHarness(Harness):\n    def importer(self, name, globals=None, locals=None, fromlist=(), level=0):\n        if name in {"html", "contextvars", "shlex"}:\n            return builtins.__import__(name, globals, locals, fromlist, level)\n        return super().importer(name, globals, locals, fromlist, level)\n\n    def scoring(self):\n        lib = self.load("lib")\n        score = self.load("score")\n        self.load("data_safety")\n        self.load("digest")\n        self.load("push_card")\n        return lib, score, self.load("run")\n\n\nclass StartupHarness(Harness):\n    def __init__(self, argv, *, missing=None, console=True, behavior="normal"):\n        super().__init__(behavior)\n        self.argv, self.missing = list(argv), missing\n        self.import_attempts, self.parsed = [], None\n        if not console:\n            self.sys.stdout = self.sys.stderr = None\n        self.original_streams = self.sys.stdout, self.sys.stderr\n        h = self\n\n        class RealParser(argparse.ArgumentParser):\n            def __init__(self, **kwargs):\n                super().__init__(prog="demand_bot.py", **kwargs)\n\n            def parse_args(self, args=None, namespace=None):\n                h.parsed = super().parse_args(h.argv if args is None else args, namespace)\n                return h.parsed\n\n            def _print_message(self, message, file=None):\n                target = h.sys.stderr if file is argparse._sys.stderr else h.sys.stdout\n                if target is not None:\n                    target.write(message)\n\n        class Loader:\n            def exec_module(self, module):\n                from test_review19_repairs import source_bytes\n                module.__dict__["__builtins__"] = {\n                    **vars(builtins), "__import__": h.importer, "open": h.open}\n                h.modules[module.__name__] = module\n                exec(compile(source_bytes(Path(module.__file__)), module.__file__, "exec"), module.__dict__)\n\n        def spec_from_file_location(name, path):\n            return types.SimpleNamespace(name=name, origin=path, loader=Loader())\n\n        def module_from_spec(spec):\n            module = types.ModuleType(spec.name)\n            module.__file__ = spec.origin\n            return module\n\n        self.effects["argparse"] = types.SimpleNamespace(ArgumentParser=RealParser)\n        self.effects["importlib.util"] = types.SimpleNamespace(\n            spec_from_file_location=spec_from_file_location, module_from_spec=module_from_spec)\n\n    def importer(self, name, globals=None, locals=None, fromlist=(), level=0):\n        if name in ("discord", "llmcall"):\n            self.import_attempts.append(name)\n            if name == self.missing:\n                raise ModuleNotFoundError(CASES["missing_message"] + " \'" + name + "\'", name=name)\n        return super().importer(name, globals, locals, fromlist, level)\n\n    def prepare(self):\n        self.load("lib")\n        self.load("data_safety")\n        self.load("private_log")\n        self.load("score")\n\n    def direct(self):\n        self.prepare()\n        return self.load("__main__", SCRIPTS / "demand_bot.py")\n\n\nclass DomainFactorTests(unittest.TestCase):\n    def test_generated_domain_pools_and_weighted_numeric_parity(self):\n        h = DomainHarness()\n        lib, score, run = h.scoring()\n        digest, push = h.modules["digest"], h.modules["push_card"]\n        for case in CASES["scores"]:\n            with self.subTest(case=case["name"]):\n                cfg = copy.deepcopy(lib.DEFAULT_CONFIG)\n                if case["weights_mode"] == "missing":\n                    cfg["scoring"].pop("rice_weights", None)\n                else:\n                    cfg["scoring"]["rice_weights"] = copy.deepcopy(case["weights"])\n                proposal = copy.deepcopy(case["proposal"])\n                before = copy.deepcopy((proposal, cfg))\n                scored = score.score_demand(proposal, cfg)\n                card = run.build_card(proposal, cfg, "synthetic-review20")\n                self.assertEqual(scored["rice_domain"], case["domain"])\n                self.assertEqual(card["rice_domain"], case["domain"])\n                self.assertEqual(card["rice_weights"], case["effective_weights"])\n                self.assertEqual(scored["rice_weights"], case["effective_weights"])\n                self.assertEqual(card["rice"], scored["rice"])\n                self.assertEqual(card["rice"]["rice_raw"], case["rice_raw"])\n                self.assertEqual(card["final_score"], case["final_score"])\n                self.assertEqual(score._final_map([proposal], None, cfg)[proposal["id"]],\n                                 case["final_score"])\n                self.assertEqual(score._final_map([proposal], case["weights"], cfg)[proposal["id"]],\n                                 case["final_score"])\n                pools = digest.split_pools([card], cfg)\n                self.assertEqual([key for key, values in pools.items() if values], [case["pool"]])\n                queue = digest.iteration_queue([card], cfg)\n                self.assertEqual(queue[0]["rice_domain"], case["domain"])\n                self.assertEqual(queue[0]["rice"]["rice_raw"], case["rice_raw"])\n                domain_text = score.domain_factor_text(card)\n                report = digest.build_markdown([card], date=CASES["date"], cfg=cfg)\n                text = push.render_text(card)\n                embed = push.build_embed(card)\n                fields = {field["name"]: field["value"] for field in embed["fields"]}\n                self.assertEqual(fields[CASES["labels"]["domain"]], domain_text)\n                for rendered in (report, text):\n                    self.assertIn(domain_text, rendered)\n                    self.assertIn(CASES["labels"]["weighted"], rendered)\n                self.assertIn(str(case["rice_raw"]), fields[CASES["labels"]["weighted"]])\n                self.assertEqual((proposal, cfg), before)\n\n    def test_weights_do_not_change_domain_pool_membership(self):\n        h = DomainHarness()\n        lib, score, run = h.scoring()\n        for case in CASES["scores"]:\n            with self.subTest(case=case["name"]):\n                cfg = copy.deepcopy(lib.DEFAULT_CONFIG)\n                if case["weights_mode"] == "missing":\n                    cfg["scoring"].pop("rice_weights", None)\n                else:\n                    cfg["scoring"]["rice_weights"] = copy.deepcopy(case["weights"])\n                card = run.build_card(case["proposal"], cfg, "synthetic-pool20")\n                pools = h.modules["digest"].split_pools([card], cfg)\n                self.assertEqual([name for name, cards in pools.items() if cards], [case["pool"]])\n\n    def test_fixed_numeric_rank_controls_remain_identical(self):\n        h = DomainHarness()\n        lib, score, run = h.scoring()\n        for case in CASES["scores"]:\n            with self.subTest(case=case["name"]):\n                cfg = copy.deepcopy(lib.DEFAULT_CONFIG)\n                if case["weights_mode"] == "missing":\n                    cfg["scoring"].pop("rice_weights", None)\n                else:\n                    cfg["scoring"]["rice_weights"] = copy.deepcopy(case["weights"])\n                scored = score.score_demand(case["proposal"], cfg)\n                card = run.build_card(case["proposal"], cfg, "synthetic-rank20")\n                self.assertEqual(scored["rice"]["rice_raw"], case["rice_raw"])\n                self.assertEqual(scored["final_score"], case["final_score"])\n                self.assertEqual(card["rice"], scored["rice"])\n                self.assertEqual(card["final_score"], scored["final_score"])\n\n    def test_live_rescorer_preserves_domain_and_weight_provenance(self):\n        h = DomainHarness()\n        lib, score, run = h.scoring()\n        h.load("private_log")\n        bot = h.load("demand_bot")\n        for case in CASES["scores"]:\n            with self.subTest(case=case["name"]):\n                cfg = copy.deepcopy(lib.DEFAULT_CONFIG)\n                if case["weights_mode"] == "missing":\n                    cfg["scoring"].pop("rice_weights", None)\n                else:\n                    cfg["scoring"]["rice_weights"] = copy.deepcopy(case["weights"])\n                row = copy.deepcopy(case["proposal"])\n                result = bot._rescorer(cfg)(row)\n                self.assertIs(result, row)\n                self.assertEqual(result["rice_domain"], case["domain"])\n                self.assertEqual(result["rice_weights"], case["effective_weights"])\n                self.assertEqual(result["rice"]["rice_raw"], case["rice_raw"])\n                self.assertEqual(result["final_score"], case["final_score"])\n\n    def test_legacy_requires_explicit_unweighted_provenance_without_losing_rank(self):\n        h = DomainHarness()\n        lib, score, run = h.scoring()\n        digest, push = h.modules["digest"], h.modules["push_card"]\n        cfg = copy.deepcopy(lib.DEFAULT_CONFIG)\n        for case in CASES["legacy_cases"]:\n            with self.subTest(case=case):\n                generated = next(item for item in CASES["scores"] if item["name"] == case["source"])\n                card = run.build_card(generated["proposal"], cfg, "synthetic-legacy")\n                card.pop("rice_domain", None)\n                card.pop("rice_weights", None)\n                card["kano"] = case["kano"]\n                if case["provenance"]:\n                    card["rice_factor_semantics"] = CASES["legacy_provenance"]\n                before = copy.deepcopy(card)\n                pools = digest.split_pools([card], cfg)\n                self.assertEqual([key for key, values in pools.items() if values], [case["pool"]])\n                queue = digest.iteration_queue([card], cfg)\n                self.assertEqual(queue[0]["rice"]["final_score"], card["final_score"])\n                if not case["provenance"]:\n                    self.assertTrue(all(value is None for value in score.domain_factors(card).values()))\n                    for rendered in (digest.build_markdown([card], date=CASES["date"], cfg=cfg),\n                                     push.render_text(card), str(push.build_embed(card))):\n                        self.assertIn(CASES["legacy_notice"], rendered)\n                        self.assertIn("re-score", rendered)\n                self.assertEqual(card, before)\n\n\nclass DirectBootstrapTests(unittest.TestCase):\n    def test_missing_optional_dependencies_preserve_primary_error_and_private_diagnostic(self):\n        for case in CASES["startup"]:\n            with self.subTest(case=case):\n                argv = list(CASES["normal_args"])\n                if case["log"]:\n                    argv += ["--log-file", CASES["log_path"]]\n                h = StartupHarness(argv, missing=case["dependency"], console=case["console"])\n                with self.assertRaises(ModuleNotFoundError) as caught:\n                    h.direct()\n                self.assertEqual(caught.exception.name, case["dependency"])\n                self.assertIsNotNone(h.parsed)\n                if case["log"]:\n                    content = h.files[CASES["log_path"]].decode()\n                    self.assertIn("ModuleNotFoundError", content)\n                    self.assertIn(case["dependency"], content)\n                    self.assertTrue(h.writes)\n                    self.assertTrue(all(state == "PRIVATE" for _, _, state in h.writes))\n                else:\n                    self.assertFalse(h.writes)\n                self.assertEqual((h.sys.stdout, h.sys.stderr), h.original_streams)\n\n    def test_help_and_invalid_choices_are_parsed_before_optional_imports(self):\n        for argv, expected in [(CASES["help_args"], 0), (CASES["invalid_args"], 2)]:\n            for console in (True, False):\n                with self.subTest(argv=argv, console=console):\n                    h = StartupHarness(argv, missing="discord", console=console)\n                    with self.assertRaises(SystemExit) as caught:\n                        h.direct()\n                    self.assertEqual(caught.exception.code, expected)\n                    self.assertFalse(h.import_attempts)\n                    self.assertFalse(h.writes)\n                    self.assertEqual((h.sys.stdout, h.sys.stderr), h.original_streams)\n\n    def test_direct_normal_modes_use_actual_parser_and_restore_streams(self):\n        for mode in CASES["normal_modes"]:\n            for console in (True, False):\n                with self.subTest(mode=mode, console=console):\n                    argv = ["--mode", mode, "--interval", "15", "--display-interval", "30",\n                            "--log-file", CASES["log_path"]]\n                    h = StartupHarness(argv, console=console)\n                    with self.assertRaises(SystemExit) as caught:\n                        h.direct()\n                    self.assertEqual(caught.exception.code, 0)\n                    self.assertEqual(h.parsed.mode, mode)\n                    self.assertEqual((h.parsed.interval, h.parsed.display_interval), (15.0, 30.0))\n                    content = h.files[CASES["log_path"]].decode()\n                    self.assertTrue(all(message in content for message in OLD_CASES["log_messages"]))\n                    self.assertEqual((h.sys.stdout, h.sys.stderr), h.original_streams)\n\n    def test_import_preserves_public_api_without_parsing_or_logging(self):\n        h = StartupHarness(CASES["invalid_args"])\n        h.prepare()\n        module = h.load("demand_bot")\n        for name in CASES["public_api"]:\n            self.assertTrue(callable(getattr(module, name)))\n        self.assertIsNone(h.parsed)\n        self.assertFalse(h.writes)\n        self.assertEqual((h.sys.stdout, h.sys.stderr), h.original_streams)\n\n    def test_refused_log_prevents_optional_imports(self):\n        h = StartupHarness(CASES["normal_args"] + ["--log-file", CASES["log_path"]], console=False)\n        h.visibility = "PUBLIC"\n        with self.assertRaises(SystemExit):\n            h.direct()\n        self.assertFalse(h.import_attempts)\n        self.assertFalse(h.writes)\n        self.assertEqual((h.sys.stdout, h.sys.stderr), h.original_streams)\n\n    def test_direct_revocation_prevents_next_append_and_restores_none_streams(self):\n        h = StartupHarness(CASES["normal_args"] + ["--log-file", CASES["log_path"]],\n                           console=False, behavior="direct-revoke")\n        with self.assertRaises(SystemExit):\n            h.direct()\n        content = h.files[CASES["log_path"]].decode()\n        self.assertIn(OLD_CASES["log_messages"][0], content)\n        self.assertNotIn(OLD_CASES["log_messages"][1], content)\n        self.assertTrue(all(state == "PRIVATE" for _, _, state in h.writes))\n        self.assertTrue(all(state == "PRIVATE" for _, state in h.opens))\n        self.assertEqual((h.sys.stdout, h.sys.stderr), h.original_streams)\n\n\nif __name__ == "__main__":\n    unittest.main()\n'



def review21_cases():
    """Fictional observations and explicit expected boundaries for review21."""
    text = "Please add CSV export retries."
    authors = ["u_" + str(i) * 16 for i in range(1, 5)]
    observations = [
        {"id": "synthetic-message-" + str(i), "author": authors[i % 4],
         "channel": "feedback" if i < 3 else "support", "text": text,
         "ts": "2026-01-15T12:00:00Z"} for i in range(12)
    ]
    candidate = dict(fixtures()["candidate"])
    candidate.update(reach=500, independent_source_count=5, internal_mentions=99,
                     authors=[{"author_hash": "u_invented"}], effort_weeks=0.5)
    candidate["evidence"] = [{"channel": "feedback", "redacted_snippet": text,
                              "origin_type": "external", "ts": observations[0]["ts"]}]
    return {
        "text": text, "authors": authors, "observations": observations,
        "verdict": fixtures()["verdict"], "candidate": candidate,
        "product": "example-product",
        "invalid_snippets": [None, "", " ", "\t\n", 7, ["synthetic"], {"text": "synthetic"}],
        "bad_scores": [None, "", "not-a-number", [], {}],
        "score_axes": ["rice", "rice_domain", "rice_weights", "opportunity_score",
                       "urgency_wsjf", "final_score", "grade", "tier", "tier_reason"],
        "dedup_words": "export retry scheduling reporting caching streaming pagination notifications "
                       "serialization validation ordering progress receipts history",
        "legacy_provenance": "unweighted",
    }

def review21_test_source():
    return '"""Generated full-module controls for evidence conservation and strict validation."""\nimport asyncio\nimport copy\nimport contextlib\nimport hashlib\nimport json\nfrom pathlib import Path\nimport types\nimport unittest\n\nfrom test_review19_repairs import ROOT, SCRIPTS, generator\nfrom test_review20_repairs import DomainHarness\n\nCASES = generator.review21_cases()\n\n\nclass Review21Harness(DomainHarness):\n    def __init__(self):\n        super().__init__()\n        self.effects["threading"] = types.SimpleNamespace(Lock=contextlib.nullcontext)\n        self.effects["msvcrt"] = self.effects["fcntl"] = None\n        self.effects["secrets"] = types.SimpleNamespace(token_hex=lambda size: "synthetic-attempt")\n        self.effects["zoneinfo"].ZoneInfoNotFoundError = KeyError\n        self.effects["redact"].pseudonymize = lambda value: "u_" + hashlib.sha256(value.encode()).hexdigest()[:16]\n        self.effects["urllib.error"] = types.SimpleNamespace(HTTPError=RuntimeError)\n        self.effects["urllib.request"] = types.SimpleNamespace(urlopen=self.forbidden)\n        async def to_thread(function, *args, **kwargs):\n            return function(*args, **kwargs)\n        self.effects["asyncio"] = types.SimpleNamespace(to_thread=to_thread)\n        self.effects["shutil"] = types.SimpleNamespace(copy2=self.forbidden)\n        self.effects["redact"].privacy_coverage = lambda: {}\n\n        self.effects["extract"] = None\n        self.pool_rows = []\n\n    def importer(self, name, globals=None, locals=None, fromlist=(), level=0):\n        if name in ("msvcrt", "fcntl"):\n            raise ImportError(name)\n        return super().importer(name, globals, locals, fromlist, level)\n\n    def ready(self):\n        lib, score, run = self.scoring()\n        self.load("verify_gate")\n        self.load("dedup")\n        run.dd = self.modules["dedup"]\n        run.gate_batch = self.modules["verify_gate"].gate_batch\n        self.load("private_log")\n        bot = self.load("demand_bot")\n        return lib, score, run, bot\n\n    def pool(self):\n        module = self.load("demand_pool")\n        module._file_lock = lambda path: contextlib.nullcontext()\n        module._read_rows = lambda path: copy.deepcopy(self.pool_rows)\n        def write(path, rows):\n            self.pool_rows = copy.deepcopy(rows)\n        module._atomic_write = write\n        return module\n\n    def proposer(self, candidates):\n        self.load("extract")\n        self.load("finalize")\n        self.load("pull_discord")\n        self.effects["llmcall"].call = lambda *a, **k: types.SimpleNamespace(\n            error=None, data={"classification": "complete", "candidates": copy.deepcopy(candidates)})\n        return self.load("scheduled")\n\n    def corpus(self, observations):\n        channels = {}\n        for item in observations:\n            channels.setdefault(item["channel"], []).append({\n                "author": item["author"], "text": item["text"], "ts": item["ts"],\n                "observation_id": item["id"], "source_id": "synthetic-source-" + item["channel"]})\n        return {"channels": channels}\n\n    def card(self):\n        self.ready()\n        tests = self.load("legacy_gate", ROOT / "skills/demand-mining/tests/test_gate_digest.py")\n        return tests._card(), self.modules["lib"].DEFAULT_CONFIG\n\n\nclass Review21Tests(unittest.TestCase):\n    def test_f7_live_score_outputs_match_card_axes(self):\n        h = Review21Harness()\n        lib, score, run, bot = h.ready()\n        proposal = copy.deepcopy(CASES["candidate"])\n        proposal.update(opportunity_score=-1, urgency_wsjf=-1, tier_reason="stale")\n        expected = run.build_card(proposal, lib.DEFAULT_CONFIG, "synthetic-run")\n        before = copy.deepcopy(proposal)\n        actual = bot._rescorer(lib.DEFAULT_CONFIG)(proposal)\n        for field in CASES["score_axes"]:\n            with self.subTest(axis=field):\n                self.assertEqual(actual[field], expected[field])\n        for field in ("reach", "importance", "satisfaction", "effort_weeks"):\n            self.assertEqual(actual[field], before[field])\n\n    def test_f8_three_internal_authors_and_replay(self):\n        h = Review21Harness()\n        lib, _, _, bot = h.ready()\n        pool = h.pool()\n        for author in CASES["authors"][:3]:\n            demand = bot._demand_from_verdict(CASES["verdict"], CASES["text"], author,\n                                             "feedback", CASES["product"])\n            _, row = pool.upsert("synthetic-pool", demand, bot._rescorer(lib.DEFAULT_CONFIG))\n            _, replay = pool.upsert("synthetic-pool", demand, bot._rescorer(lib.DEFAULT_CONFIG))\n            self.assertEqual({**row, "last_seen": None}, {**replay, "last_seen": None})\n        self.assertEqual(row["reach"], 3)\n        self.assertEqual(row.get("internal_mentions", 0), 3)\n        self.assertEqual(row["rice_domain"]["confidence"], 0.8)\n\n    def test_f8_sources_same_text_and_display_cap(self):\n        h = Review21Harness()\n        lib, _, _, bot = h.ready()\n        pool = h.pool()\n        for item in CASES["observations"]:\n            message = types.SimpleNamespace(id=item["id"], channel=types.SimpleNamespace(id=item["channel"]))\n            kwargs = bot._message_observation(message) if hasattr(bot, "_message_observation") else {}\n            demand = bot._demand_from_verdict(CASES["verdict"], item["text"], item["author"],\n                                             item["channel"], CASES["product"], **kwargs)\n            _, row = pool.upsert("synthetic-pool", demand, bot._rescorer(lib.DEFAULT_CONFIG))\n        self.assertEqual(row["independent_source_count"], 2)\n        self.assertEqual(row["reach"], 4)\n        self.assertEqual(row.get("internal_mentions", 0), 4)\n        self.assertEqual(row.get("observation_count", 0), 12)\n        self.assertEqual(len(row["evidence"]), pool._MAX_EVIDENCE)\n        _, replay = pool.upsert("synthetic-pool", demand, bot._rescorer(lib.DEFAULT_CONFIG))\n        self.assertEqual({**row, "last_seen": None}, {**replay, "last_seen": None})\n\n    def test_f8_repeated_author_does_not_create_three_author_band(self):\n        h = Review21Harness()\n        lib, _, _, bot = h.ready()\n        pool = h.pool()\n        for i in range(4):\n            demand = bot._demand_from_verdict(CASES["verdict"], CASES["text"] + str(i),\n                                             CASES["authors"][0], "feedback", CASES["product"])\n            _, row = pool.upsert("synthetic-pool", demand, bot._rescorer(lib.DEFAULT_CONFIG))\n        self.assertEqual(row["reach"], 1)\n        self.assertEqual(row.get("internal_mentions", 0), 1)\n        self.assertEqual(row["rice_domain"]["confidence"], 0.5)\n\n    def test_f8_direct_context_is_not_attributed_to_current_author(self):\n        h = Review21Harness()\n        lib, _, _, bot = h.ready()\n        captured = []\n        h.effects["demand_pool"].upsert = lambda path, demand, rescore: (captured.append(demand) or "new", demand)\n        owner = object.__new__(bot.DemandBot)\n        owner.poolp, owner.rescore = "synthetic-pool", bot._rescorer(lib.DEFAULT_CONFIG)\n        owner._pool_product = lambda: CASES["product"]\n        entry = {"m": types.SimpleNamespace(id="synthetic-message", channel=types.SimpleNamespace(\n                    id="synthetic-channel", name="feedback")),\n                 "text": CASES["text"], "ah": CASES["authors"][0],\n                 "context": "Another author discussed an unrelated feature.",\n                 "verdict": CASES["verdict"], "reply": "synthetic reply", "reply_attempted": True}\n        coroutine = owner._complete_direct(entry)\n        with self.assertRaises(StopIteration):\n            coroutine.send(None)\n        self.assertEqual(captured[0]["evidence"][0]["redacted_snippet"], CASES["text"])\n        self.assertEqual(captured[0]["authors"][0]["author_hash"], CASES["authors"][0])\n\n    def test_f9_model_counts_authors_and_origins_are_corpus_bound(self):\n        h = Review21Harness()\n        lib, _, run, _ = h.ready()\n        candidate = copy.deepcopy(CASES["candidate"])\n        corpus = h.corpus(CASES["observations"][:1])\n        proposed = h.proposer([candidate]).propose(corpus, lib.DEFAULT_CONFIG)[0]\n        self.assertEqual(proposed["reach"], 1)\n        self.assertEqual(proposed["independent_source_count"], 1)\n        self.assertEqual(proposed["internal_mentions"], 1)\n        self.assertEqual([a["author_hash"] for a in proposed["authors"]], [CASES["authors"][0]])\n        self.assertEqual(proposed["evidence"][0]["origin_type"], "internal")\n        merged = run.merge_candidates([proposed, copy.deepcopy(proposed)])[0]\n        card = run.build_card(merged, lib.DEFAULT_CONFIG, "synthetic-run")\n        self.assertEqual(card["rice_domain"]["reach"], 1)\n        self.assertEqual(card["independent_source_count"], 1)\n        self.assertEqual(h.modules["verify_gate"].gate_batch([card], lib.DEFAULT_CONFIG)["pushable"], [])\n\n    def test_f9_duplicate_corpus_rows_and_legitimate_multi_source(self):\n        h = Review21Harness()\n        lib, _, run, _ = h.ready()\n        candidate = copy.deepcopy(CASES["candidate"])\n        second = copy.deepcopy(candidate)\n        second["evidence"][0]["channel"] = "support"\n        observations = CASES["observations"][:2] + [CASES["observations"][3]]\n        corpus = h.corpus(observations + observations)\n        proposed = h.proposer([candidate, second]).propose(corpus, lib.DEFAULT_CONFIG)\n        merged = run.merge_candidates(proposed + proposed)[0]\n        self.assertEqual(merged["reach"], 3)\n        self.assertEqual(merged["independent_source_count"], 2)\n        self.assertEqual(merged["internal_mentions"], 3)\n        self.assertEqual(len(merged["evidence"]), 3)\n        self.assertEqual(merged.get("observation_count"), 3)\n        self.assertEqual(run.build_card(merged, lib.DEFAULT_CONFIG, "synthetic-run")["rice_domain"]["confidence"], 1)\n\n    def test_f9_unobserved_quote_and_identity_are_rejected(self):\n        for field, value in (("redacted_snippet", "unobserved synthetic quote"),\n                             ("observation_id", "invented-observation"),\n                             ("channel", "invented-source")):\n            with self.subTest(field=field):\n                h = Review21Harness()\n                lib, _, _, _ = h.ready()\n                candidate = copy.deepcopy(CASES["candidate"])\n                candidate["evidence"][0][field] = value\n                with self.assertRaises(ValueError):\n                    h.proposer([candidate]).propose(h.corpus(CASES["observations"][:1]), lib.DEFAULT_CONFIG)\n\n    def test_f10_reject_empty_missing_and_nontextual_internal_snippets(self):\n        h = Review21Harness()\n        card, cfg = h.card()\n        gate = h.modules["verify_gate"]\n        self.assertTrue(gate.validate_card(card, cfg)[0])\n        for origin in ("internal", None):\n            for snippet in CASES["invalid_snippets"]:\n                with self.subTest(origin=origin, snippet=snippet):\n                    bad = copy.deepcopy(card)\n                    bad["evidence"][0]["redacted_snippet"] = snippet\n                    bad["evidence"][0]["origin_type"] = origin\n                    self.assertFalse(gate.validate_card(bad, cfg)[0])\n                    self.assertFalse(gate.gate_batch([bad], cfg)["passed"])\n\n    def test_f10_blocked_card_cannot_complete_real_run_path(self):\n        h = Review21Harness()\n        lib, _, run, _ = h.ready()\n        finalizer = h.load("finalize")\n        calls = []\n        finalizer.require_private = lambda path: {"path": str(path)}\n        finalizer.file_lock = lambda *a, **k: contextlib.nullcontext()\n        finalizer.atomic_json = lambda *a, **k: calls.append("write") or h.forbidden()\n        ledger = types.SimpleNamespace(list_active=lambda: [], upsert=lambda *a, **k: calls.append("upsert"))\n        candidate = copy.deepcopy(CASES["candidate"])\n        candidate["evidence"][0].update(origin_type="internal", redacted_snippet="")\n        cfg = copy.deepcopy(lib.DEFAULT_CONFIG)\n        cfg.update(product_id=CASES["product"], timezone="UTC")\n        identity = {"product_id": CASES["product"], "date": "2026-01-15", "timezone": "UTC",\n                    "source_window": {"start": "2026-01-15T00:00:00Z", "end": "2026-01-16T00:00:00Z"}}\n        collection = {"status": "complete", "classification": "complete", "source_count": 1, "source_window": identity["source_window"]}\n        with self.assertRaisesRegex(ValueError, "candidate validation failed"):\n            finalizer.finalize([candidate], cfg, ledger=ledger, dry_run=False,\n                identity=identity, collection=collection, archive_dir=h.root, attempt_id="synthetic")\n        self.assertEqual(calls, [])\n\n    def test_f11_malformed_score_keeps_batch_diagnostics(self):\n        h = Review21Harness()\n        card, cfg = h.card()\n        bad = []\n        for value in CASES["bad_scores"]:\n            item = copy.deepcopy(card)\n            item["final_score"] = value\n            bad.append(item)\n        result = h.modules["verify_gate"].gate_batch(bad + [card], cfg)\n        self.assertEqual(len(result["blocked"]), len(bad))\n        self.assertEqual(result["passed"], [card])\n        self.assertTrue(all("final_score missing/non-numeric" in x["errors"] for x in result["blocked"]))\n\n    def test_f12_high_similarity_requires_subject_and_entities(self):\n        h = Review21Harness()\n        lib, _, _, _ = h.ready()\n        dd = h.modules["dedup"]\n        words = CASES["dedup_words"]\n        candidate = {"canonical_key": "alpha|export::integrations", "title": "alpha " + words}\n        row = {"idempotency_key": "beta|export::integrations", "ext": {\n            dd.EXT + "text": "beta " + words, dd.EXT + "simhash": 0}}\n        self.assertGreaterEqual(lib.jaccard(dd._token_set(candidate["title"]),\n                                           dd._token_set(row["ext"][dd.EXT + "text"])), 0.83)\n        self.assertFalse(dd._subject_agree(candidate["title"], row["ext"][dd.EXT + "text"]))\n        self.assertIsNone(dd.match_existing(candidate, [row], lib.DEFAULT_CONFIG))\n        candidate["canonical_key"] = "other::unrelated"\n        row["ext"][dd.EXT + "text"] = candidate["title"]\n        self.assertIsNone(dd.match_existing(candidate, [row], lib.DEFAULT_CONFIG))\n        candidate["canonical_key"] = row["idempotency_key"]\n        self.assertIs(dd.match_existing(candidate, [row], lib.DEFAULT_CONFIG), row)\n\n    def test_f12_original_rewrites_and_candidate_band_preserved(self):\n        h = Review21Harness()\n        lib, _, _, _ = h.ready()\n        tests = h.load("old_dedup_tests", ROOT / "skills/demand-mining/tests/test_dedup_pool.py")\n        tests.test_near_dup_rewrite_matches()\n        dd = h.modules["dedup"]\n        cfg = copy.deepcopy(lib.DEFAULT_CONFIG)\n        cfg["scoring"].update(candidate_merge_band=[0.5, 0.99], dedup_cosine_threshold=0.99)\n        words = CASES["dedup_words"]\n        candidate = {"canonical_key": "alpha|export::integrations", "title": "alpha " + words}\n        text = "alpha " + words + " synthetic"\n        row = {"idempotency_key": "alpha|export|synthetic::integrations", "ext": {\n            dd.EXT + "text": text, dd.EXT + "simhash": lib.simhash(text)}}\n        self.assertIsNotNone(dd.in_candidate_band(candidate, [row], cfg))\n        self.assertIsNone(dd.match_existing(candidate, [row], cfg))\n\n\nif __name__ == "__main__":\n    unittest.main()\n'

def review21_legacy_gate_source():
    return '"""T4, verify gate (schema + >=1 internal evidence + egress DLP, fail-closed) and EOD digest\n(quick-win/big-bet split, iteration queue order, catch-up dates, empty-day honesty)."""\nfrom lib import load_config\nfrom verify_gate import validate_card, gate_batch\nfrom digest import (split_pools, iteration_queue, missed_digest_dates, build_markdown,\n                    build_headlines)\nfrom redact import redact as _core_redact\nimport push_card as _pc\n\nCFG = load_config()\n\n\ndef _card(score=80, tier="tier1", n=2, internal=True, pii=False, kano="performance"):\n    ev = [{"channel": "discord" if internal else "reddit", "origin_type":\n           "internal" if internal else "external", "redacted_snippet": "the export is slow",\n           "ts": "2026-06-25T11:00:00Z"},\n          {"channel": "reddit", "origin_type": "external", "redacted_snippet": "same issue",\n           "ts": "2026-06-25T10:00:00Z"}]\n    return {"canonical_key": "k|export::integrations", "taxonomy_track": "integrations",\n            "rice": {"reach": 5, "impact": 2, "confidence": 1.0, "effort": 2, "rice_raw": 5},\n            "opportunity_score": 12, "urgency_wsjf": 4, "kano": kano,\n            "final_score": score, "grade": "B", "tier": tier,\n            "independent_source_count": n, "evidence": ev,\n            "title": "contact bob@example.com" if pii else "faster csv export",\n            "why": "users churn", "recommendation": "stream the export"}\n\n\n# ---------------------------------------------------------------- T4 gate\ndef test_full_card_passes():\n    ok, errs = validate_card(_card(), CFG)\n    assert ok, errs\n\n\ndef test_blocks_no_internal_evidence():\n    c = _card(internal=False)\n    c["evidence"] = [{"channel": "reddit", "origin_type": "external",\n                      "redacted_snippet": "x", "ts": "2026-06-25T10:00:00Z"}]\n    ok, errs = validate_card(c, CFG)\n    assert not ok and any("internal evidence" in e for e in errs)\n\n\ndef test_blocks_residual_pii_egress():\n    ok, errs = validate_card(_card(pii=True), CFG)\n    assert not ok and any("PII" in e for e in errs)\n\n\ndef test_push_grade_needs_two_sources():\n    ok, errs = validate_card(_card(score=90, n=1), CFG)\n    assert not ok and any("independent_source_count" in e for e in errs)\n\n\ndef test_tier0_pushable_regardless_of_score():\n    low_t0 = _card(score=10, tier="tier0", kano="must_be")\n    g = gate_batch([low_t0], CFG)\n    assert low_t0 in g["pushable"]        # stop-the-bleed bypasses the score floor\n\n\ndef test_empty_day_honest():\n    g = gate_batch([_card(score=10, tier="backlog")], CFG)\n    assert g["empty_day"] is True and g["pushable"] == []\n\n\ndef test_push_cap():\n    cards = []\n    for i in range(8):\n        c = _card(score=90, tier="tier1")\n        c["canonical_key"] = f"k{i}"\n        c["title"] = f"demand-{i}"\n        cards.append(c)\n    g = gate_batch(cards, CFG)\n    assert len(g["pushable"]) <= CFG["push"]["max_per_day"]\n\n\n# ---------------------------------------------------------------- digest / brainstorm\ndef test_split_pools_quickwin_bigbet():\n    qw = _card(score=80)\n    qw["opportunity_score"] = 15\n    qw["rice"] = {"reach": 5, "impact": 2, "confidence": 1.0, "effort": 2, "rice_raw": 5}\n    qw["rice_factor_semantics"] = "unweighted"\n    qw["kano"] = "performance"\n    bb = _card(score=70)\n    bb["kano"] = "delighter"\n    pools = split_pools([qw, bb], CFG)\n    assert qw in pools["quick_win"]\n    assert bb in pools["big_bet"]\n\n\ndef test_iteration_queue_tier_order():\n    t0 = _card(score=30, tier="tier0"); t0["canonical_key"] = "a"\n    t1 = _card(score=90, tier="tier1"); t1["canonical_key"] = "b"\n    bk = _card(score=50, tier="backlog"); bk["canonical_key"] = "c"\n    q = iteration_queue([bk, t1, t0], CFG)\n    assert [x["tier"] for x in q] == ["tier0", "tier1", "backlog"]\n    assert q[0]["order"] == 1\n\n\ndef test_iteration_queue_excludes_cut_noise():\n    # Kano indifferent/reverse => tier "cut" (砍, do not build). A cut demand is noise and must\n    # NOT surface as an iteration direction; only real (non-cut) demands are recommended.\n    cut = _card(score=5, tier="cut", kano="indifferent"); cut["canonical_key"] = "noise|x::other"\n    real = _card(score=80, tier="tier1", kano="performance"); real["canonical_key"] = "real|y::ui-ux"\n    q = iteration_queue([cut, real], CFG)\n    assert all(x["tier"] != "cut" for x in q), [x["tier"] for x in q]\n    assert [x["canonical_key"] for x in q] == ["real|y::ui-ux"]\n    assert q[0]["order"] == 1                      # order numbers stay contiguous after the drop\n    # all-noise day yields an empty actionable queue (no filler iteration directions)\n    assert iteration_queue([cut], CFG) == []\n\n\ndef test_empty_day_markdown_honest():\n    md = build_markdown([], {"candidates": 0}, cfg=CFG)\n    assert "今日无合格新需求" in md\n\n\n# ---------------------------------------------------------------- T7 catch-up\ndef test_catchup_normal_one_day():\n    dates = missed_digest_dates("2026-06-24T12:00:00Z", "2026-06-25T12:00:00Z")\n    assert dates == ["2026-06-25"]\n\n\ndef test_catchup_same_day_rerun_empty():\n    assert missed_digest_dates("2026-06-25T08:00:00Z", "2026-06-25T12:00:00Z") == []\n\n\ndef test_catchup_overslept_backfill_bounded():\n    dates = missed_digest_dates("2026-01-01T00:00:00Z", "2026-06-25T12:00:00Z", cap=30)\n    assert len(dates) == 30 and dates[-1] == "2026-06-25"\n\n\ndef test_catchup_cold_start_no_storm():\n    assert missed_digest_dates("", "2026-06-25T12:00:00Z") == ["2026-06-25"]\n\n\n# ---------------------------------------------------------------- batch-2 R1 (T4): cut noise must\n# not leak into the Big-bet pool. Batch 1 dropped Kano cut/indifferent from the iteration_queue,\n# but split_pools still routed a high-impact/low-confidence indifferent card into big_bet, so it\n# was recommended as a "Big-bet" iteration direction in the EOD markdown (recommending noise).\ndef test_split_pools_excludes_cut_noise():\n    noise = {"kano": "indifferent", "tier": "cut", "opportunity_score": 2,\n             "final_score": 30, "title": "noise idea", "canonical_key": "n::other",\n             "rice": {"impact": 3.0, "confidence": 0.5, "effort": 2.0, "rice_raw": 2.25}}\n    real = _card()\n    pools = split_pools([noise, real], CFG)\n    flat = pools["quick_win"] + pools["big_bet"] + pools["other"]\n    assert noise not in flat, "Kano cut/indifferent noise must not enter any brainstorm pool"\n    assert real in flat, "a genuine demand must still be pooled (no over-filter)"\n    md = build_markdown([noise, real], date="2026-06-25")\n    assert "noise idea" not in md, "cut noise must never be recommended in the EOD digest"\n\n\n# ---------------------------------------------------------------- batch-2 R2 (T4): a day whose only\n# cards are Kano cut/noise has zero actionable demands => the digest must print the honest empty-day\n# message, NOT a dangling "迭代方向队列" header with no items (filler-by-omission).\ndef test_all_cut_day_is_honest_empty():\n    cards = [{"kano": "indifferent", "tier": "cut", "opportunity_score": 1, "final_score": 10,\n              "title": "noise1", "canonical_key": "a::other",\n              "rice": {"impact": 1, "confidence": 1, "effort": 2, "rice_raw": 0.5}},\n             {"kano": "reverse", "tier": "cut", "opportunity_score": 1, "final_score": 5,\n              "title": "noise2", "canonical_key": "b::other",\n              "rice": {"impact": 1, "confidence": 1, "effort": 2, "rice_raw": 0.2}}]\n    md = build_markdown(cards, date="2026-06-25")\n    assert "今日无合格新需求" in md, "all-cut day must emit the honest empty-day message"\n    assert "迭代方向队列" not in md, "must not emit a dangling empty iteration-queue header"\n\n\n# ---------------------------------------------------------------- batch-3 R2 (T4 count conservation):\n# batches 1-2 correctly dropped Kano cut/noise from the iteration queue AND every brainstorm pool,\n# but the EOD coverage header still printed "合格 {len(cards)}" counting the cut noise, so the\n# header OVER-reported the qualified/actionable count vs the rendered body (a reader sees 合格 2 but\n# only 1 queue item). Conservation: the 合格 header must equal the actionable queue, and the cut\n# count must be surfaced so actionable + cut == total reconciles.\ndef test_eod_coverage_count_excludes_cut_noise():\n    import re\n    real = _card()  # tier1 performance = actionable\n    noise = {"kano": "indifferent", "tier": "cut", "opportunity_score": 1, "final_score": 70,\n             "title": "noise idea", "canonical_key": "n::other",\n             "rice": {"impact": 1, "confidence": 1, "effort": 2, "rice_raw": 0.5}}\n    md = build_markdown([real, noise], coverage={"internal": 2}, date="2026-06-25")\n    q = iteration_queue([real, noise], CFG)\n    m = re.search(r"合格 (\\d+)", md)\n    assert m and int(m.group(1)) == len(q) == 1, "合格 header must match the actionable queue (cut excluded)"\n    assert re.search(r"剔噪 (\\d+)", md).group(1) == "1", "the excluded cut-noise count must be surfaced"\n    # a pure-real day is unchanged (no over-correction): 合格 == total, 剔噪 0\n    md2 = build_markdown([real], coverage={"internal": 1}, date="2026-06-25")\n    assert re.search(r"合格 (\\d+)", md2).group(1) == "1"\n    assert re.search(r"剔噪 (\\d+)", md2).group(1) == "0"\n\n\n# ---------------------------------------------------------------- batch-4 R1 (T6 egress DLP): the\n# fail-closed PII scan only covered top-level user-visible fields (title/summary/...), but\n# evidence[].redacted_snippet is ALSO rendered into the pushed card and archived to the pool, a\n# residual email/phone hiding in a snippet rode straight through validate_card (ok=True) and leaked.\n# Architecture §4 / T6: nothing with leftover PII may ever be pushed/archived (落池后无邮箱/电话).\ndef test_blocks_residual_pii_in_evidence_snippet():\n    c = _card()                                   # clean top-level fields\n    c["evidence"][0]["redacted_snippet"] = "pls email me at alice@example.com about this"\n    ok, errs = validate_card(c, CFG)\n    assert not ok and any("PII" in e and "evidence" in e for e in errs)\n\n\ndef test_clean_evidence_snippet_still_passes():   # reverse: no false-positive on clean snippets\n    ok, errs = validate_card(_card(), CFG)\n    assert ok, errs\n\n\n# ---------------------------------------------------------------- headlines (pushed daily message)\ndef test_headlines_rank_tag_and_meta():\n    t0 = _card(score=90, tier="tier0", kano="must_be")\n    t0["title"] = "批量导出对账单"\n    t1 = _card(score=60, tier="tier1", kano="performance")\n    t1["title"] = "移动端离线草稿"\n    h = build_headlines([t1, t0], {"candidates": 7}, date="2026-07-15", cap=5)\n    # tier0 ranks above tier1 regardless of input order; bold numbered headline + 领域=urgency·need\n    assert h.index("批量导出对账单") < h.index("移动端离线草稿")\n    assert "**1.【立即·刚需】批量导出对账单**" in h\n    assert "**2.【本周·期望】移动端离线草稿**" in h\n    assert "📊 **需求头条** · 2026-07-15" in h\n    assert "证据" in h and "RICE=" in h\n\n\ndef test_headlines_cap_and_overflow_note():\n    cards = [_card(score=90 - i, tier="tier1") for i in range(8)]\n    for i, c in enumerate(cards):\n        c["title"] = f"需求{i}"\n        c["canonical_key"] = f"k|{i}"\n    h = build_headlines(cards, cap=5, date="2026-07-15")\n    assert "精选 5" in h and "合格 8" in h\n    assert "另有 3 条" in h                      # overflow acknowledged, not silently dropped\n\n\ndef test_headlines_excludes_cut_noise():\n    real = _card(score=80, tier="tier1", kano="performance"); real["title"] = "真需求"\n    noise = _card(score=50, tier="cut", kano="indifferent"); noise["title"] = "噪声"\n    h = build_headlines([real, noise], date="2026-07-15")\n    assert "真需求" in h and "噪声" not in h\n    assert "剔噪 1" in h\n\n\ndef test_headlines_empty_day_is_honest():\n    assert "今日无合格新需求" in build_headlines([], {"candidates": 0}, date="2026-07-15")\n    # an all-cut day is also an honest empty day (no filler headline)\n    cut = _card(tier="cut", kano="reverse")\n    assert "今日无合格新需求" in build_headlines([cut], date="2026-07-15")\n\n\ndef test_headlines_prose_from_why_and_recommendation():\n    c = _card(tier="tier0", kano="must_be")\n    c["why"] = "用户反复手动导出，耗时且易错"\n    c["recommendation"] = "一键区间导出"\n    h = build_headlines([c], date="2026-07-15")\n    assert "用户反复手动导出" in h and "建议：一键区间导出" in h\n    assert "。。" not in h                        # sentence-join must not double a full stop\n\n\ndef test_headlines_carries_no_url_and_passes_egress_gate():\n    # demand-mining\'s egress deliver() aborts on ANY url/handle; the headlines must therefore contain\n    # neither, and the date header / year ranges must NOT trip the core phone matcher.\n    c = _card(tier="tier1"); c["why"] = "2020-2026 讨论持续升温，是高频痛点"\n    h = build_headlines([c], date="2026-07-15", digest_hint="私有归档 2026/2026-07-15.md")\n    assert "http" not in h and "@" not in h\n    assert not _core_redact(h)["found"], "headlines must be clean for the fail-closed has_pii gate"\n    ok, detail = _pc.deliver(h, dry_run=True)\n    assert ok is True and "dry-run" in detail    # gate does not abort a clean headlines message\n\n\ndef test_headlines_robust_to_malformed_score():\n    # score.py always emits a numeric final_score, but a hand-built/malformed card must not crash the\n    # build: None sorts as 0 and shows \'?\'; a non-numeric string must not raise in the sort key.\n    bad = [{"tier": "tier1", "title": "空分数", "final_score": None, "canonical_key": "k|a"},\n           {"tier": "tier1", "title": "坏分数", "final_score": "NaNlike", "canonical_key": "k|b"},\n           {"tier": "tier0", "title": "正常", "final_score": 90, "grade": "A", "canonical_key": "k|c"}]\n    h = build_headlines(bad, date="2026-07-15")           # must not raise\n    assert "正常" in h and "空分数" in h and "坏分数" in h\n    assert "None" not in h                                 # explicit-None score renders \'?\', never \'None\'\n\n\ndef test_headlines_injection_neutralized():\n    c = _card(tier="tier0", kano="must_be")\n    c["title"] = "evil`code`\\n|table"            # backticks / pipe / newline in an (untrusted) field\n    h = build_headlines([c], date="2026-07-15")\n    line = [ln for ln in h.splitlines() if "evil" in ln][0]\n    assert "`" not in line and "|" not in line and "\\n" not in line.rstrip()\n\n\ndef test_inline_normalizes_en_em_dashes_at_runtime():\n    # runtime injection: an LLM-supplied demand field must never carry an en/em dash into the push.\n    import digest as _dg\n    em, en, bar = chr(0x2014), chr(0x2013), chr(0x2015)\n    assert _dg._inline("batch" + em + "export") == "batch, export"\n    for d in (em, en, bar):\n        assert d not in _dg._inline("p " + d + " q")\n'


def review22_cases():
    """Generator-owned observations for identity and corroboration boundaries."""
    import copy
    base = review21_cases()
    timestamp = "2026-01-15T12:00:00Z"
    text = "please add batch export"
    authors = ["u_" + format(i, "016x") for i in range(1, 9)]
    candidate = copy.deepcopy(base["candidate"])
    candidate.update(title="batch export", summary=text, inferred_job="export reports",
                     track="core-workflow", why="export needs retries", recommendation="add retries")
    candidate["evidence"] = [{"channel": "feedback", "origin_type": "internal",
                              "redacted_snippet": text, "ts": timestamp}]
    verdict = copy.deepcopy(base["verdict"])
    verdict.update(title="batch export", track="core-workflow", why="export needs retries")
    channels = [{"id": str(810000000000000001 + i), "name": name}
                for i, name in enumerate(("feedback", "support"))]
    messages = {
        item["id"]: [{"id": str(820000000000000001 + i),
                      "author": {"id": str(830000000000000001 + i)},
                      "content": text, "timestamp": timestamp}]
        for i, item in enumerate(channels)
    }
    external = {"source": "synthetic-forum", "origin_type": "external",
                "redacted_snippet": "batch export needs retries", "ts": timestamp}
    return {
        "salt": "synthetic-review22-salt", "text": text, "timestamp": timestamp,
        "product": "example-product", "candidate": candidate, "verdict": verdict,
        "authors": authors, "channels": channels, "messages": messages,
        "window": {"start": "2026-01-15T00:00:00Z", "end": "2026-01-16T00:00:00Z"},
        "external": external,
        "external_claim": {"internal_count": 2, "external_origin_count": 400},
        "legacy_numeric_claim": 99999,
        "raw_token": "SYNTHETIC0a1B2c3D4e5F6g7H8i9J0k1L2m3N4p5Q6r7S8t9U",
        "huge_scores": [int("9" * 400), -int("9" * 400)],
        "valid_card": {
            "canonical_key": "synthetic-batch-export", "title": "batch export",
            "summary": text, "inferred_job": "export reports", "taxonomy_track": "core-workflow",
            "rice": {"rice_raw": 1}, "opportunity_score": 5, "urgency_wsjf": 1,
            "final_score": 50, "tier": "backlog", "kano": "performance",
            "independent_source_count": 1,
            "evidence": [{"channel": "feedback", "origin_type": "internal",
                          "redacted_snippet": text, "ts": timestamp}],
        },
    }

def review22_test_source():
    """Generate the real-redactor, memory-persistence regression suite."""
    return '"""Generated real-redactor controls for Demand22; external effects are memory-only."""\nimport builtins\nimport contextlib\nimport copy\nimport io\nimport json\nimport types\nimport unittest\n\nfrom test_review19_repairs import generator\nfrom test_review21_repairs import Review21Harness\n\nCASES = generator.review22_cases()\n\n\nclass Review22Harness(Review21Harness):\n    def __init__(self):\n        super().__init__()\n        append_open = self.open\n        def memory_open(path, mode="r", **kwargs):\n            if mode == "r":\n                return io.StringIO(self.files[str(path)].decode(kwargs.get("encoding", "utf-8")))\n            return append_open(path, mode, **kwargs)\n        self.open = memory_open\n        self.os.path.isfile = lambda path: str(path) in self.files\n        self.os.environ["DEMAND_MINING_NOW"] = CASES["timestamp"]\n        self.redactor = self.load("redact")\n        self.redactor._EPHEMERAL_SALT = CASES["salt"].encode()\n\n    def importer(self, name, globals=None, locals=None, fromlist=(), level=0):\n        if name in {"collections", "hmac", "unicodedata"}:\n            return builtins.__import__(name, globals, locals, fromlist, level)\n        return super().importer(name, globals, locals, fromlist, level)\n\n    def pool(self):\n        module = self.load("demand_pool")\n        module._file_lock = lambda path: contextlib.nullcontext()\n        def write(path, payload):\n            if not isinstance(payload, bytes):\n                raise AssertionError("serializer did not produce bytes")\n            self.files[str(path)] = payload\n        self.modules["data_safety"].atomic_bytes = write\n        return module\n\n    def collected(self, count=2):\n        self.ready()\n        pull = self.load("pull_discord")\n        batches = copy.deepcopy(CASES["messages"])\n        pull._get = lambda channel, token, before: batches.pop(str(channel), [])\n        return pull.pull(CASES["channels"][:count], "synthetic-token",\n                         source_window=CASES["window"])\n\n    def proposed(self, corpus, candidate=None):\n        candidate = copy.deepcopy(candidate or CASES["candidate"])\n        return self.proposer([candidate]).propose(corpus, self.modules["lib"].DEFAULT_CONFIG)[0]\n\n    def demand(self, author, *, text=None, source="feedback"):\n        return self.modules["demand_bot"]._demand_from_verdict(\n            CASES["verdict"], text or CASES["text"], author, source, CASES["product"],\n            timestamp=CASES["timestamp"])\n\n    def matched(self, card):\n        dd = self.modules["dedup"]\n        return {"ext": {\n            dd.EXT + "last_score": card["final_score"],\n            dd.EXT + "source_set": card["source_set"],\n            dd.EXT + "tier": card.get("tier"),\n            dd.EXT + "external_corroboration": {"external_origin_count": 0},\n        }}\n\n\nclass Review22Tests(unittest.TestCase):\n    def test_f13_real_collector_redactor_and_proposer_preserve_single_author(self):\n        h = Review22Harness()\n        corpus = h.collected(1)\n        row = corpus["channels"]["feedback"][0]\n        raw = CASES["messages"][CASES["channels"][0]["id"]][0]\n        expected = h.redactor.pseudonymize(raw["author"]["id"])\n        self.assertEqual(row["author_hash"], expected)\n        self.assertNotIn("author", row)\n        clean = h.redactor.safe_data(corpus)\n        self.assertEqual(clean, corpus)\n        proposed = h.proposed(corpus)\n        self.assertEqual([a["author_hash"] for a in proposed["authors"]], [expected])\n        self.assertEqual(proposed["reach"], 1)\n        self.assertEqual(proposed["internal_mentions"], 1)\n\n    def test_f13_multi_source_scheduled_and_live_observations_agree(self):\n        h = Review22Harness()\n        corpus = h.collected(2)\n        candidate = copy.deepcopy(CASES["candidate"])\n        candidate["evidence"].append({**candidate["evidence"][0], "channel": "support"})\n        proposed = h.proposed(corpus, candidate)\n        observed = []\n        for channel in CASES["channels"]:\n            raw = CASES["messages"][channel["id"]][0]\n            row = corpus["channels"][channel["name"]][0]\n            message = types.SimpleNamespace(id=raw["id"], channel=types.SimpleNamespace(id=channel["id"]))\n            info = h.modules["demand_bot"]._message_observation(message)\n            self.assertEqual(info["source_id"], row["source_id"])\n            self.assertEqual(info["observation_id"], row["observation_id"])\n            live = h.modules["demand_bot"]._demand_from_verdict(\n                CASES["verdict"], row["text"], row["author_hash"], channel["name"],\n                CASES["product"], source_id=info["source_id"], observation_id=info["observation_id"],\n                timestamp=row["ts"])\n            observed.extend(live["observation_index"])\n        self.assertEqual({x["observation_id"] for x in proposed["observation_index"]},\n                         {x["observation_id"] for x in observed})\n        self.assertEqual(proposed["reach"], 2)\n        self.assertEqual(proposed["independent_source_count"], 2)\n\n    def test_f13_legacy_author_alias_is_idempotent_and_conflicts_are_rejected(self):\n        h = Review22Harness()\n        corpus = h.collected(1)\n        row = corpus["channels"]["feedback"][0]\n        row["author"] = row.pop("author_hash")\n        expected = row["author"]\n        self.assertEqual(h.proposed(corpus)["authors"][0]["author_hash"], expected)\n        first = h.redactor.safe_data(corpus)\n        self.assertEqual(h.redactor.safe_data(first), first)\n        with self.assertRaisesRegex(ValueError, "conflicting author"):\n            h.redactor.safe_data({"author": CASES["authors"][0], "author_hash": CASES["authors"][1]})\n\n    def test_f14_typed_identifiers_survive_but_free_text_and_credentials_are_screened(self):\n        h = Review22Harness()\n        lib, _, _, _ = h.ready()\n        identity = lib.observation_identity("feedback", CASES["authors"][0],\n                                            CASES["timestamp"], CASES["text"])\n        typed = {"observation_id": identity, "source_id": identity}\n        self.assertEqual(h.redactor.safe_data(typed), typed)\n        for field in ("text", "summary", "untyped_metadata"):\n            screened = h.redactor.safe_data({field: identity})\n            self.assertNotEqual(screened[field], identity)\n        self.assertNotEqual(h.redactor.safe_data({"source_id": CASES["raw_token"]})["source_id"],\n                            CASES["raw_token"])\n        self.assertEqual(h.redactor.safe_data({"observation_id": CASES["authors"][0]})["observation_id"],\n                         CASES["authors"][0])\n\n    def test_f14_generated_fallbacks_survive_actual_pool_serialization_reload_and_replay(self):\n        h = Review22Harness()\n        lib, _, _, bot = h.ready()\n        pool = h.pool()\n        ids = set()\n        for i, author in enumerate(CASES["authors"][:3]):\n            demand = h.demand(author, text=CASES["text"] + " " + str(i))\n            ids.add(demand["observation_index"][0]["observation_id"])\n            _, row = pool.upsert("synthetic-pool", demand, bot._rescorer(lib.DEFAULT_CONFIG))\n            self.assertEqual(pool.load("synthetic-pool", product_id=CASES["product"]), [row])\n        self.assertEqual(len(ids), 3)\n        self.assertEqual({x["observation_id"] for x in row["observation_index"]}, ids)\n        before = copy.deepcopy(row)\n        _, replay = pool.upsert("synthetic-pool", demand, bot._rescorer(lib.DEFAULT_CONFIG))\n        self.assertEqual(before, replay)\n        self.assertEqual(len(pool.load("synthetic-pool", product_id=CASES["product"])), 1)\n\n    def test_f14_actual_discord_namespace_cap_and_replay_are_preserved(self):\n        h = Review22Harness()\n        lib, _, _, bot = h.ready()\n        pool = h.pool()\n        all_ids = set()\n        for i in range(12):\n            channel = CASES["channels"][i % 2]\n            message = types.SimpleNamespace(id=str(840000000000000000 + i),\n                                           channel=types.SimpleNamespace(id=channel["id"]))\n            info = bot._message_observation(message)\n            demand = bot._demand_from_verdict(CASES["verdict"], CASES["text"],\n                CASES["authors"][i % 4], channel["name"], CASES["product"],\n                source_id=info["source_id"], observation_id=info["observation_id"],\n                timestamp=CASES["timestamp"])\n            all_ids.add(info["observation_id"])\n            _, row = pool.upsert("synthetic-pool", demand, bot._rescorer(lib.DEFAULT_CONFIG))\n        self.assertEqual(len(row["evidence"]), 8)\n        self.assertEqual(row["observation_count"], 12)\n        self.assertEqual(row["reach"], 4)\n        self.assertEqual(row["independent_source_count"], 2)\n        self.assertEqual({x["observation_id"] for x in row["observation_index"]}, all_ids)\n        _, replay = pool.upsert("synthetic-pool", demand, bot._rescorer(lib.DEFAULT_CONFIG))\n        self.assertEqual(replay, row)\n\n    def test_f15_legacy_authors_survive_three_updates_with_or_without_old_snippets(self):\n        for has_snippets in (False, True):\n            with self.subTest(has_snippets=has_snippets):\n                h = Review22Harness()\n                lib, _, _, bot = h.ready()\n                pool = h.pool()\n                incoming = h.demand(CASES["authors"][3])\n                legacy = {k: copy.deepcopy(v) for k, v in incoming.items()\n                          if k not in {"evidence", "observation_index", "authors"}}\n                legacy.update(authors=[{"author_hash": a, "urgency": "need", "segment": "free"}\n                                       for a in CASES["authors"][:3]],\n                              reach=CASES["legacy_numeric_claim"], observation_count=CASES["legacy_numeric_claim"])\n                legacy["evidence"] = ([{k: v for k, v in incoming["evidence"][0].items()\n                                        if k not in {"observation_id", "source_id", "author_hash"}}]\n                                      if has_snippets else [])\n                h.files["synthetic-pool"] = (json.dumps(legacy) + "\\n").encode()\n                for i, author in enumerate(CASES["authors"][3:6], 1):\n                    _, row = pool.upsert("synthetic-pool", h.demand(author), bot._rescorer(lib.DEFAULT_CONFIG))\n                    self.assertEqual(row["canonical_key"], incoming["canonical_key"])\n                    self.assertEqual(row["reach"], 3 + i)\n                    self.assertEqual({a["author_hash"] for a in row["authors"]}, set(CASES["authors"][:3 + i]))\n                    self.assertEqual(len(pool.load("synthetic-pool", product_id=CASES["product"])), 1)\n                    self.assertEqual(row["observation_count"], i + int(has_snippets))\n                _, replay = pool.upsert("synthetic-pool", h.demand(CASES["authors"][5]),\n                                        bot._rescorer(lib.DEFAULT_CONFIG))\n                self.assertEqual(replay, row)\n\n    def test_f15_retained_authors_survive_existing_index_without_numeric_invention(self):\n        h = Review22Harness()\n        lib, _, _, _ = h.ready()\n        current = h.demand(CASES["authors"][3])\n        current["authors"] += [{"author_hash": a} for a in CASES["authors"][:3]]\n        current["reach"] = CASES["legacy_numeric_claim"]\n        for author in CASES["authors"][4:6]:\n            current.update(lib.merge_observations(current, h.demand(author)))\n        self.assertEqual(current["reach"], 6)\n        self.assertEqual(current["internal_mentions"], 3)\n        self.assertEqual(current["observation_count"], 3)\n\n    def test_f16_grounding_projection_and_dedup_reject_unobserved_evolution_claims(self):\n        h = Review22Harness()\n        corpus = h.collected(1)\n        candidate = copy.deepcopy(CASES["candidate"])\n        candidate.update(external_corroboration=CASES["external_claim"],\n                         competitor_status="shipped", competitor_ref="invented", velocity=99)\n        proposed = h.proposed(corpus, candidate)\n        self.assertEqual(proposed["external_corroboration"]["external_origin_count"], 0)\n        for key in ("competitor_status", "competitor_ref", "velocity"):\n            self.assertNotIn(key, proposed)\n        lib, run, dd = h.modules["lib"], h.modules["run"], h.modules["dedup"]\n        card = run.build_card(proposed, lib.DEFAULT_CONFIG, "synthetic-run")\n        self.assertEqual(card["external_corroboration"]["external_origin_count"], 0)\n        self.assertEqual(dd.decide(card, h.matched(card), lib.DEFAULT_CONFIG)["branch"], dd.SUPPRESS)\n\n    def test_f16_direct_count_and_incomplete_external_events_cannot_resurface(self):\n        h = Review22Harness()\n        lib, _, run, _ = h.ready()\n        dd = h.modules["dedup"]\n        card = run.build_card(CASES["candidate"], lib.DEFAULT_CONFIG, "synthetic-run")\n        matched = h.matched(card)\n        card["external_corroboration"] = CASES["external_claim"]\n        self.assertEqual(dd.decide(card, matched, lib.DEFAULT_CONFIG)["branch"], dd.SUPPRESS)\n        for key, invalid in (("ts", "not-a-date"), ("source", ""), ("redacted_snippet", "")):\n            broken = {**CASES["external"], key: invalid}\n            card["evidence"] = [broken]\n            decision = dd.decide(card, matched, lib.DEFAULT_CONFIG)\n            self.assertFalse(decision["delta"]["external_corroboration_new"])\n            self.assertEqual(decision["branch"], dd.SUPPRESS)\n\n    def test_f16_real_external_event_resurfaces_once(self):\n        h = Review22Harness()\n        lib, _, run, _ = h.ready()\n        dd = h.modules["dedup"]\n        candidate = copy.deepcopy(CASES["candidate"])\n        candidate["evidence"].append(copy.deepcopy(CASES["external"]))\n        card = run.build_card(candidate, lib.DEFAULT_CONFIG, "synthetic-run")\n        matched = h.matched(card)\n        self.assertEqual(card["external_corroboration"]["external_origin_count"], 1)\n        decision = dd.decide(card, matched, lib.DEFAULT_CONFIG)\n        self.assertEqual(decision["branch"], dd.RESURFACE)\n        self.assertTrue(decision["delta"]["external_corroboration_new"])\n        matched["ext"][dd.EXT + "external_corroboration"] = card["external_corroboration"]\n        self.assertEqual(dd.decide(card, matched, lib.DEFAULT_CONFIG)["branch"], dd.SUPPRESS)\n\n    def test_f17_both_json_integer_overflows_keep_neighbor_and_blocked_diagnostics(self):\n        h = Review22Harness()\n        lib, _, _, _ = h.ready()\n        cards = [copy.deepcopy(CASES["valid_card"])]\n        for value in CASES["huge_scores"]:\n            cards.append({**copy.deepcopy(CASES["valid_card"]), "final_score": value})\n        cards = json.loads(json.dumps(cards))\n        result = h.modules["verify_gate"].gate_batch(cards, lib.DEFAULT_CONFIG)\n        self.assertEqual(result["passed"], cards[:1])\n        self.assertEqual(len(result["blocked"]), 2)\n        self.assertTrue(all("final_score missing/non-numeric" in item["errors"] for item in result["blocked"]))\n\n\nif __name__ == "__main__":\n    unittest.main()\n'



