def review23_test_source():
    """Return generated controls without executing product code."""
    return '"""Generated synthetic count and author-alias controls for Demand23."""\nimport copy\nimport itertools\nimport json\nimport unittest\n\nfrom test_review19_repairs import generator\nfrom test_review22_repairs import Review22Harness\n\nCASES = generator.review23_cases()\n\n\nclass Review23Tests(unittest.TestCase):\n    def test_f18_extreme_json_counts_block_with_neighbor_and_diagnostic(self):\n        for encoded_count in CASES["overflow_count_json"]:\n            with self.subTest(encoded_count=encoded_count):\n                h = Review22Harness()\n                lib, _, _, _ = h.ready()\n                valid = copy.deepcopy(CASES["valid_card"])\n                broken = copy.deepcopy(valid)\n                broken["independent_source_count"] = "SYNTHETIC_COUNT_PLACEHOLDER"\n                wire = json.dumps([broken, valid]).replace(\n                    \'"SYNTHETIC_COUNT_PLACEHOLDER"\', encoded_count)\n                cards = json.loads(wire)\n                before = copy.deepcopy(cards)\n                result = h.modules["verify_gate"].gate_batch(cards, lib.DEFAULT_CONFIG)\n                self.assertEqual(result["passed"], [valid])\n                self.assertEqual(result["archivable"], [valid])\n                self.assertFalse(result["empty_day"])\n                self.assertEqual(len(result["blocked"]), 1)\n                self.assertIn("independent_source_count non-numeric",\n                              result["blocked"][0]["errors"])\n                self.assertEqual(cards, before)\n\n    def test_f18_ordinary_counts_keep_existing_batch_behavior(self):\n        for case in CASES["ordinary_counts"]:\n            with self.subTest(label=case["label"]):\n                h = Review22Harness()\n                lib, _, _, _ = h.ready()\n                card = {**copy.deepcopy(CASES["valid_card"]),\n                        "final_score": case["score"],\n                        "independent_source_count": case["value"]}\n                result = h.modules["verify_gate"].gate_batch([card], lib.DEFAULT_CONFIG)\n                self.assertEqual(bool(result["passed"]), case["passes"])\n                self.assertEqual(len(result["blocked"]), int(not case["passes"]))\n                self.assertEqual(bool(result["pushable"]), case["pushable"])\n                if case["error"]:\n                    self.assertTrue(any(case["error"] in message\n                                        for message in result["blocked"][0]["errors"]))\n\n    def test_f19_all_alias_pairs_reject_malformed_values_in_both_orders(self):\n        for good_key, bad_key in itertools.permutations(CASES["alias_keys"], 2):\n            for malformed in CASES["malformed_authors"]:\n                for reverse in (False, True):\n                    with self.subTest(good_key=good_key, bad_key=bad_key,\n                                      malformed=malformed["label"], reverse=reverse):\n                        h = Review22Harness()\n                        pairs = [(good_key, CASES["pseudonym"]),\n                                 (bad_key, copy.deepcopy(malformed["value"]))]\n                        if reverse:\n                            pairs.reverse()\n                        value = dict(pairs)\n                        before = copy.deepcopy(value)\n                        with self.assertRaisesRegex(ValueError, "invalid author identity type"):\n                            h.redactor.safe_data(value)\n                        self.assertEqual(value, before)\n\n    def test_f19_standalone_and_nested_malformed_aliases_are_rejected(self):\n        for key in CASES["alias_keys"]:\n            for malformed in CASES["malformed_authors"]:\n                for nested in (False, True):\n                    with self.subTest(key=key, malformed=malformed["label"], nested=nested):\n                        h = Review22Harness()\n                        value = {key: copy.deepcopy(malformed["value"])}\n                        if nested:\n                            value = {"observations": [value]}\n                        with self.assertRaisesRegex(ValueError, "invalid author identity type"):\n                            h.redactor.safe_data(value)\n\n    def test_f19_valid_scalar_aliases_stay_order_independent_and_idempotent(self):\n        for raw in CASES["valid_author_scalars"]:\n            h = Review22Harness()\n            expected = (raw if raw == CASES["pseudonym"]\n                        else h.redactor.pseudonymize(str(raw)))\n            for keys in itertools.permutations(CASES["alias_keys"]):\n                with self.subTest(raw=raw, keys=keys):\n                    value = {key: raw for key in keys}\n                    before = copy.deepcopy(value)\n                    normalized = h.redactor.safe_data(value)\n                    self.assertEqual(normalized, {"author_hash": expected})\n                    self.assertEqual(h.redactor.safe_data(normalized), normalized)\n                    self.assertEqual(value, before)\n\n\nif __name__ == "__main__":\n    unittest.main()\n'


def review24_cases():
    """Synthetic legacy evidence with unknown attribution and known neighbors."""
    import copy
    base = review22_cases()
    return {
        "evidence": copy.deepcopy(base["candidate"]["evidence"][0]),
        "authors": list(base["authors"]),
        "product": base["product"],
        "legacy_numeric_claim": base["legacy_numeric_claim"],
        "legacy_author_counts": [0, 2],
    }


def review24_test_source():
    """Generated unknown historical attribution controls."""
    return '"""Generated unknown historical attribution controls for Demand24."""\nimport copy\nimport json\nimport unittest\n\nfrom test_review19_repairs import generator\nfrom test_review22_repairs import Review22Harness\n\nCASES = generator.review24_cases()\n\n\nclass Review24Tests(unittest.TestCase):\n    def test_unknown_author_is_absent_and_repeated_screening_is_stable(self):\n        h = Review22Harness()\n        lib, _, _, _ = h.ready()\n        original = copy.deepcopy(CASES["evidence"])\n        fact = lib.evidence_observation(original)\n        self.assertNotIn("author_hash", fact)\n        self.assertTrue(fact["explicit"])\n        self.assertEqual(h.redactor.safe_data(fact), fact)\n        merged = lib.merge_observations({"evidence": [original], "authors": []})\n        self.assertEqual(original, CASES["evidence"])\n        self.assertEqual(merged["reach"], 0)\n        self.assertEqual(merged["internal_mentions"], 0)\n        self.assertEqual(merged["observation_count"], 1)\n        self.assertEqual(merged["independent_source_count"], 1)\n        for item in merged["evidence"] + merged["observation_index"]:\n            self.assertNotIn("author_hash", item)\n        self.assertEqual(h.redactor.safe_data(merged), merged)\n        self.assertEqual(lib.merge_observations(merged), merged)\n\n    def test_legacy_unknown_snippet_survives_serialization_updates_and_replay(self):\n        for legacy_author_count in CASES["legacy_author_counts"]:\n            with self.subTest(legacy_author_count=legacy_author_count):\n                h = Review22Harness()\n                lib, _, _, bot = h.ready()\n                pool = h.pool()\n                incoming = h.demand(CASES["authors"][3])\n                legacy = {key: copy.deepcopy(value) for key, value in incoming.items()\n                          if key not in {"evidence", "observation_index", "authors"}}\n                known = CASES["authors"][:legacy_author_count]\n                legacy.update(\n                    authors=[{"author_hash": author, "urgency": "need", "segment": "free"}\n                             for author in known],\n                    evidence=[copy.deepcopy(CASES["evidence"])],\n                    reach=CASES["legacy_numeric_claim"],\n                    observation_count=CASES["legacy_numeric_claim"])\n                h.files["synthetic-pool"] = (json.dumps(legacy) + "\\n").encode()\n                unknown_id = None\n                for count, author in enumerate(CASES["authors"][3:6], 1):\n                    demand = h.demand(author)\n                    _, row = pool.upsert("synthetic-pool", demand,\n                                         bot._rescorer(lib.DEFAULT_CONFIG))\n                    unknown = [fact for fact in row["observation_index"]\n                               if "author_hash" not in fact]\n                    self.assertEqual(len(unknown), 1)\n                    if unknown_id is None:\n                        unknown_id = unknown[0]["observation_id"]\n                    self.assertEqual(unknown[0]["observation_id"], unknown_id)\n                    snippets = [item for item in row["evidence"]\n                                if item["observation_id"] == unknown_id]\n                    self.assertEqual(len(snippets), 1)\n                    self.assertNotIn("author_hash", snippets[0])\n                    for key, value in CASES["evidence"].items():\n                        self.assertEqual(snippets[0][key], value)\n                    self.assertEqual(row["reach"], legacy_author_count + count)\n                    self.assertEqual({item["author_hash"] for item in row["authors"]},\n                                     set(known + CASES["authors"][3:3 + count]))\n                    self.assertEqual(row["internal_mentions"], count)\n                    self.assertEqual(row["observation_count"], count + 1)\n                    self.assertEqual(h.redactor.safe_data(row), row)\n                    self.assertEqual(pool.load("synthetic-pool", product_id=CASES["product"]), [row])\n                before = copy.deepcopy(row)\n                _, replay = pool.upsert("synthetic-pool", demand,\n                                        bot._rescorer(lib.DEFAULT_CONFIG))\n                self.assertEqual(replay, before)\n\n    def test_legacy_nullable_index_normalizes_without_reassigning_unknown_author(self):\n        h = Review22Harness()\n        lib, _, _, _ = h.ready()\n        fact = lib.evidence_observation(CASES["evidence"])\n        fact["author_hash"] = None\n        snippet = {**copy.deepcopy(CASES["evidence"]),\n                   "observation_id": fact["observation_id"],\n                   "source_id": fact["source_id"], "author_hash": None}\n        legacy = {"authors": [{"author_hash": CASES["authors"][0]}],\n                  "observation_index": [fact], "evidence": [snippet]}\n        before = copy.deepcopy(legacy)\n        merged = lib.merge_observations(legacy)\n        self.assertEqual(legacy, before)\n        self.assertEqual(merged["authors"], legacy["authors"])\n        self.assertEqual(merged["reach"], 1)\n        self.assertEqual(merged["internal_mentions"], 0)\n        self.assertEqual(merged["observation_count"], 1)\n        for item in merged["evidence"] + merged["observation_index"]:\n            self.assertNotIn("author_hash", item)\n            self.assertEqual(item["observation_id"], fact["observation_id"])\n        self.assertEqual(h.redactor.safe_data(merged), merged)\n        self.assertEqual(lib.merge_observations(merged), merged)\n\n    def test_unique_legacy_author_and_explicit_known_author_are_preserved(self):\n        for explicit in (False, True):\n            with self.subTest(explicit=explicit):\n                h = Review22Harness()\n                lib, _, _, _ = h.ready()\n                authors = CASES["authors"][:2 if explicit else 1]\n                evidence = copy.deepcopy(CASES["evidence"])\n                expected = authors[-1]\n                if explicit:\n                    evidence["author_hash"] = expected\n                record = {"authors": [{"author_hash": author} for author in authors],\n                          "evidence": [evidence]}\n                before = copy.deepcopy(record)\n                merged = lib.merge_observations(record)\n                self.assertEqual(record, before)\n                self.assertEqual(merged["reach"], len(authors))\n                self.assertEqual(merged["internal_mentions"], 1)\n                self.assertEqual(merged["observation_count"], 1)\n                self.assertEqual(merged["observation_index"][0]["author_hash"], expected)\n                self.assertEqual(merged["evidence"][0]["author_hash"], expected)\n                self.assertEqual(h.redactor.safe_data(merged), merged)\n                self.assertEqual(lib.merge_observations(merged), merged)\n\n\nif __name__ == "__main__":\n    unittest.main()\n'


def review25_cases():
    """Synthetic stored-pool compatibility and strict-boundary scenarios."""
    import copy
    base = review22_cases()
    product_a, product_b = base["product"], "acme-alt"
    def row(product, key, number, unknown):
        identity = "obs_" + format(number, "064x")
        source_id = "obs_" + format(100 + number, "064x")
        author = None if unknown else base["authors"][1]
        evidence = {
            "observation_id": identity, "source_id": source_id,
            "channel": "feedback", "origin_type": "internal",
            "ts": base["timestamp"], "redacted_snippet": base["text"],
            "author_hash": author,
        }
        fact = {
            "observation_id": identity, "source_id": source_id,
            "source": "feedback", "origin_type": "internal",
            "explicit": True, "author_hash": author,
        }
        result = {
            "canonical_key": key, "title": "Export preview",
            "summary": "Show a preview before exporting the selected items.",
            "status": "new", "first_seen": base["timestamp"],
            "last_seen": base["timestamp"], "final_score": 25,
            "authors": [{"author_hash": base["authors"][0 if unknown else 1]}],
            "evidence": [evidence], "observation_index": [fact],
            "reach": 1, "internal_mentions": 0 if unknown else 1,
            "observation_count": 1, "independent_source_count": 1,
            "source_set": ["feedback"], "metadata": {"retained": "synthetic-history"},
        }
        if product is not None:
            result["product_id"] = product
        return result
    return {
        "products": [product_a, product_b], "timestamp": base["timestamp"],
        "authors": list(base["authors"]), "new_key": "export-new",
        "missing_key": "export-absent",
        "rows": [
            row(product_a, "export-unknown", 1, True),
            row(product_b, "export-unknown", 2, True),
            row(product_a, "export-known", 3, False),
            row(None, "export-legacy", 4, True),
        ],
        "aliases": ["author_hash", "author", "user_id"],
        "new_alias_locations": ["root", "metadata", "evidence", "observation_index", "authors"],
        "rescore_targets": ["new", "known", "unknown"],
        "invalid_ids": [None, "", False, 7, "observation-untyped", "obs_short",
                        "obs_" + "z" * 64],
        "unsupported_authors": [False, [], {}],
        "typed_ids": ["obs_" + "a" * 64, "u_" + "b" * 16],
    }



def review25_test_source():
    'Generated whole-pool legacy compatibility controls.'
    return '"""Generated stored-pool compatibility controls for Demand25."""\nimport copy\nimport json\nimport unittest\n\nfrom test_review19_repairs import generator\nfrom test_review22_repairs import Review22Harness\n\nCASES = generator.review25_cases()\nPATH = "synthetic-pool"\n\n\ndef encoded(rows):\n    return "".join(json.dumps(row, ensure_ascii=False) + "\\n" for row in rows).encode("utf-8")\n\n\ndef decoded(h):\n    return [json.loads(line) for line in h.files[PATH].decode("utf-8").splitlines()]\n\n\ndef expected_rows():\n    # The expected migration changes only the two canonical null author fields.\n    rows = copy.deepcopy(CASES["rows"])\n    for index in (0, 1, 3):\n        for field in ("evidence", "observation_index"):\n            del rows[index][field][0]["author_hash"]\n    return rows\n\n\ndef put_alias(row, location, alias, value):\n    if location == "root":\n        row[alias] = value\n    elif location == "metadata":\n        row.setdefault("metadata", {})[alias] = value\n    else:\n        row[location][0][alias] = value\n\n\nclass Review25Tests(unittest.TestCase):\n    def fixture(self):\n        h = Review22Harness()\n        lib, _, _, bot = h.ready()\n        pool = h.pool()\n        h.files[PATH] = encoded(CASES["rows"])\n        h.atomic_calls = []\n        original = h.modules["data_safety"].atomic_bytes\n        def capture(path, payload):\n            h.atomic_calls.append((path, payload))\n            original(path, payload)\n        h.modules["data_safety"].atomic_bytes = capture\n        return h, lib, bot, pool\n\n    def demand(self, h, product=None, key=None):\n        demand = h.demand(CASES["authors"][5])\n        demand["product_id"] = product or CASES["products"][0]\n        demand["canonical_key"] = key or CASES["new_key"]\n        return demand\n\n    def assert_no_write(self, h, before):\n        self.assertEqual(h.files[PATH], before)\n        self.assertEqual(h.atomic_calls, [])\n\n    def test_load_normalizes_view_without_persisting_or_changing_product_selection(self):\n        h, _, _, pool = self.fixture()\n        before = h.files[PATH]\n        expected = expected_rows()\n        for product in CASES["products"]:\n            with self.subTest(product=product):\n                self.assertEqual(pool.load(PATH, product_id=product),\n                                 [row for row in expected if row.get("product_id") == product])\n        self.assert_no_write(h, before)\n\n    def test_unrelated_insert_in_each_product_persists_all_legacy_rows_without_recounting(self):\n        for product in CASES["products"]:\n            with self.subTest(product=product):\n                h, lib, bot, pool = self.fixture()\n                demand = self.demand(h, product=product)\n                original = copy.deepcopy(demand)\n                action, created = pool.upsert(PATH, demand, bot._rescorer(lib.DEFAULT_CONFIG))\n                self.assertEqual(action, "new")\n                self.assertEqual(demand, original)\n                self.assertEqual(decoded(h), expected_rows() + [created])\n                self.assertEqual(len(h.atomic_calls), 1)\n                self.assertEqual(created["product_id"], product)\n                self.assertEqual(h.redactor.safe_data(decoded(h)), decoded(h))\n\n    def test_unrelated_merge_preserves_other_products_and_unassigned_history(self):\n        h, lib, bot, pool = self.fixture()\n        expected = expected_rows()\n        target = expected[2]\n        action, merged = pool.upsert(\n            PATH, self.demand(h, key=target["canonical_key"]),\n            bot._rescorer(lib.DEFAULT_CONFIG))\n        self.assertEqual(action, "merged")\n        expected[2] = merged\n        self.assertEqual(decoded(h), expected)\n        self.assertEqual(merged["reach"], 2)\n        self.assertEqual(merged["observation_count"], 2)\n        self.assertEqual(merged["internal_mentions"], 2)\n        self.assertEqual(len(h.atomic_calls), 1)\n\n    def test_unknown_target_keeps_unknown_identity_and_replay_is_byte_stable(self):\n        h, lib, bot, pool = self.fixture()\n        demand = self.demand(h, key=CASES["rows"][0]["canonical_key"])\n        action, merged = pool.upsert(PATH, demand, bot._rescorer(lib.DEFAULT_CONFIG))\n        self.assertEqual(action, "merged")\n        unknown_id = CASES["rows"][0]["observation_index"][0]["observation_id"]\n        for field in ("evidence", "observation_index"):\n            unknown = [item for item in merged[field] if item["observation_id"] == unknown_id]\n            self.assertEqual(len(unknown), 1)\n            self.assertNotIn("author_hash", unknown[0])\n        self.assertEqual({author["author_hash"] for author in merged["authors"]},\n                         {CASES["authors"][0], CASES["authors"][5]})\n        self.assertEqual(merged["reach"], 2)\n        self.assertEqual(merged["observation_count"], 2)\n        self.assertEqual(merged["internal_mentions"], 1)\n        expected = expected_rows()\n        expected[0] = merged\n        self.assertEqual(decoded(h), expected)\n        before = h.files[PATH]\n        _, replay = pool.upsert(PATH, demand, bot._rescorer(lib.DEFAULT_CONFIG))\n        self.assertEqual(replay, merged)\n        self.assertEqual(h.files[PATH], before)\n        self.assertEqual(len(h.atomic_calls), 2)\n\n    def test_status_writes_nullable_and_unrelated_targets_with_exact_product_isolation(self):\n        for target_index in (0, 1, 2):\n            with self.subTest(target_index=target_index):\n                h, _, _, pool = self.fixture()\n                expected = expected_rows()\n                target = expected[target_index]\n                self.assertTrue(pool.set_status(PATH, target["canonical_key"], "planned",\n                                                product_id=target["product_id"]))\n                target["status"] = "planned"\n                target["last_seen"] = CASES["timestamp"]\n                self.assertEqual(decoded(h), expected)\n                self.assertEqual(len(h.atomic_calls), 1)\n\n    def test_legacy_attribution_persists_all_rows_and_preserves_unknown_observations(self):\n        for product in CASES["products"]:\n            with self.subTest(product=product):\n                h, _, _, pool = self.fixture()\n                expected = expected_rows()\n                self.assertTrue(pool.attribute_legacy(\n                    PATH, expected[3]["canonical_key"], product_id=product))\n                expected[3]["product_id"] = product\n                self.assertEqual(decoded(h), expected)\n                self.assertEqual(pool.load(PATH, product_id=product),\n                                 [row for row in expected if row.get("product_id") == product])\n                self.assertEqual(len(h.atomic_calls), 1)\n\n    def test_no_matching_status_or_attribution_leaves_original_nullable_bytes(self):\n        h, _, _, pool = self.fixture()\n        before = h.files[PATH]\n        self.assertFalse(pool.set_status(PATH, CASES["missing_key"], "ack",\n                                         product_id=CASES["products"][0]))\n        self.assertFalse(pool.attribute_legacy(PATH, CASES["missing_key"],\n                                               product_id=CASES["products"][0]))\n        self.assert_no_write(h, before)\n\n    def test_new_null_aliases_remain_strict_in_every_location(self):\n        for alias in CASES["aliases"]:\n            for location in CASES["new_alias_locations"]:\n                with self.subTest(alias=alias, location=location):\n                    h, _, _, pool = self.fixture()\n                    before = h.files[PATH]\n                    demand = self.demand(h)\n                    put_alias(demand, location, alias, None)\n                    original = copy.deepcopy(demand)\n                    with self.assertRaisesRegex(ValueError, "invalid author identity type"):\n                        pool.upsert(PATH, demand)\n                    self.assertEqual(demand, original)\n                    self.assert_no_write(h, before)\n\n    def test_rescore_cannot_introduce_null_aliases_on_new_or_merged_rows(self):\n        for target in CASES["rescore_targets"]:\n            for alias in CASES["aliases"]:\n                for location in ("root", "evidence", "observation_index"):\n                    with self.subTest(target=target, alias=alias, location=location):\n                        h, _, _, pool = self.fixture()\n                        before = h.files[PATH]\n                        key = (CASES["rows"][2 if target == "known" else 0]["canonical_key"]\n                               if target != "new" else CASES["new_key"])\n                        def rescore(row):\n                            put_alias(row, location, alias, None)\n                            return row\n                        with self.assertRaisesRegex(ValueError, "invalid author identity type"):\n                            pool.upsert(PATH, self.demand(h, key=key), rescore)\n                        self.assert_no_write(h, before)\n\n    def test_stored_unidentified_or_malformed_observation_does_not_gain_legacy_exception(self):\n        for field in ("evidence", "observation_index"):\n            for identity in CASES["invalid_ids"]:\n                with self.subTest(field=field, identity=identity):\n                    h, _, _, pool = self.fixture()\n                    rows = copy.deepcopy(CASES["rows"])\n                    item = rows[0][field][0]\n                    if identity is None:\n                        del item["observation_id"]\n                    else:\n                        item["observation_id"] = identity\n                    h.files[PATH] = encoded(rows)\n                    before = h.files[PATH]\n                    with self.assertRaisesRegex(ValueError, "invalid author identity type"):\n                        pool.set_status(PATH, rows[2]["canonical_key"], "ack",\n                                        product_id=CASES["products"][0])\n                    self.assert_no_write(h, before)\n\n    def test_stored_null_alias_outside_canonical_slots_remains_strict(self):\n        locations = ("root", "metadata", "authors", "evidence", "observation_index")\n        for location in locations:\n            for alias in CASES["aliases"]:\n                if location in ("evidence", "observation_index") and alias == "author_hash":\n                    continue\n                with self.subTest(location=location, alias=alias):\n                    h, _, _, pool = self.fixture()\n                    rows = copy.deepcopy(CASES["rows"])\n                    put_alias(rows[0], location, alias, None)\n                    h.files[PATH] = encoded(rows)\n                    before = h.files[PATH]\n                    with self.assertRaisesRegex(ValueError, "invalid author identity type"):\n                        pool.set_status(PATH, rows[2]["canonical_key"], "ack",\n                                        product_id=CASES["products"][0])\n                    self.assert_no_write(h, before)\n\n    def test_stored_competing_alias_cannot_replace_unknown_attribution(self):\n        for field in ("evidence", "observation_index"):\n            for alias in ("author", "user_id"):\n                with self.subTest(field=field, alias=alias):\n                    h, _, _, pool = self.fixture()\n                    rows = copy.deepcopy(CASES["rows"])\n                    rows[0][field][0][alias] = CASES["authors"][2]\n                    h.files[PATH] = encoded(rows)\n                    before = h.files[PATH]\n                    with self.assertRaisesRegex(ValueError, "invalid author identity type"):\n                        pool.set_status(PATH, rows[2]["canonical_key"], "ack",\n                                        product_id=CASES["products"][0])\n                    self.assert_no_write(h, before)\n\n    def test_unsupported_stored_author_types_are_not_normalized(self):\n        for field in ("evidence", "observation_index"):\n            for value in CASES["unsupported_authors"]:\n                with self.subTest(field=field, value=value):\n                    h, _, _, pool = self.fixture()\n                    rows = copy.deepcopy(CASES["rows"])\n                    rows[0][field][0]["author_hash"] = copy.deepcopy(value)\n                    h.files[PATH] = encoded(rows)\n                    before = h.files[PATH]\n                    with self.assertRaisesRegex(ValueError, "invalid author identity type"):\n                        pool.set_status(PATH, rows[2]["canonical_key"], "ack",\n                                        product_id=CASES["products"][0])\n                    self.assert_no_write(h, before)\n\n    def test_both_canonical_typed_id_formats_preserve_unknown_and_counts(self):\n        for identity in CASES["typed_ids"]:\n            with self.subTest(identity=identity):\n                h, _, _, pool = self.fixture()\n                rows = copy.deepcopy(CASES["rows"])\n                for field in ("evidence", "observation_index"):\n                    rows[0][field][0]["observation_id"] = identity\n                h.files[PATH] = encoded(rows)\n                expected = expected_rows()\n                for field in ("evidence", "observation_index"):\n                    expected[0][field][0]["observation_id"] = identity\n                self.assertTrue(pool.set_status(PATH, rows[2]["canonical_key"], "ack",\n                                                product_id=CASES["products"][0]))\n                expected[2]["status"] = "ack"\n                self.assertEqual(decoded(h), expected)\n\n    def test_conflicting_legacy_attribution_preserves_original_bytes(self):\n        for conflict in ("duplicate-legacy", "attributed"):\n            with self.subTest(conflict=conflict):\n                h, _, _, pool = self.fixture()\n                rows = copy.deepcopy(CASES["rows"])\n                extra = copy.deepcopy(rows[3])\n                if conflict == "attributed":\n                    extra["product_id"] = CASES["products"][0]\n                rows.append(extra)\n                h.files[PATH] = encoded(rows)\n                before = h.files[PATH]\n                with self.assertRaisesRegex(ValueError, "legacy attribution conflicts"):\n                    pool.attribute_legacy(PATH, rows[3]["canonical_key"],\n                                          product_id=CASES["products"][0])\n                self.assert_no_write(h, before)\n\n\nif __name__ == "__main__":\n    unittest.main()\n'


def storage_boundary_test_source():
    return '"""Generated native DATA boundary regressions; reproduce with tools/make_fixtures.py."""\nimport json\nimport os\nfrom pathlib import Path\nimport socket\nimport subprocess\nimport sys\nimport datetime\n\nimport pytest\n\nimport data_safety\nimport dedup\nfrom private_log import PrivateLog, PrivateLogError\n\nREMINDER = Path.home() / \'.claude/skills/schedule-reminder/scripts/reminder.py\'\n\n\n@pytest.fixture\ndef native_storage(tmp_path, monkeypatch):\n    for key in list(os.environ):\n        if key.upper().startswith((\'GIT_\', \'DEMAND_MINING_\', \'SCHEDULE_\')):\n            monkeypatch.delenv(key, raising=False)\n    profile = tmp_path / \'profile\'\n    profile.mkdir()\n    monkeypatch.setenv(\'HOME\', str(profile))\n    monkeypatch.setenv(\'USERPROFILE\', str(profile))\n    monkeypatch.setenv(\'GIT_CONFIG_NOSYSTEM\', \'1\')\n    monkeypatch.setenv(\'GIT_CONFIG_GLOBAL\', os.devnull)\n    monkeypatch.setenv(\'GIT_TERMINAL_PROMPT\', \'0\')\n\n    def no_network(*args, **kwargs):\n        raise AssertionError(\'native storage regression attempted network access\')\n    monkeypatch.setattr(socket.socket, \'connect\', no_network)\n    receipts = {}\n\n    def repository(path, name, visibility):\n        path.mkdir(parents=True)\n        for args in [(\'init\', \'-q\'), (\'config\', \'remote.origin.url\',\n                                     \'https://github.com/example-owner/\'+name+\'.git\')]:\n            subprocess.run([\'git\', \'-C\', str(path), *args], capture_output=True, check=True)\n        subprocess.run([\'git\', \'-C\', str(path), \'-c\', \'user.name=Synthetic Fixture\',\n                        \'-c\', \'user.email=user1@example.com\', \'commit\', \'--allow-empty\',\n                        \'-m\', \'Initialize synthetic companion\'], capture_output=True, check=True)\n        receipts[\'example-owner/\'+name] = visibility\n        target = profile / \'.pii-guard/visibility.json\'\n        target.parent.mkdir(exist_ok=True)\n        target.write_text(json.dumps({**receipts, \'_refreshed\': datetime.datetime.now(datetime.timezone.utc).isoformat(), \'_verified\': {\n            key: {\'v\': value} for key, value in receipts.items()}}), encoding=\'utf-8\')\n        return path\n\n    from native_fixture import native_reminder\n    monkeypatch.setattr(sys.modules[__name__], \'REMINDER\', native_reminder(tmp_path, REMINDER))\n    private = repository(tmp_path/\'private\', \'private-vault\', \'PRIVATE\')\n    public = repository(tmp_path/\'public\', \'public-tool\', \'PUBLIC\')\n    return private, public, repository\n\n\n@pytest.mark.parametrize(\'verb\', [\'init\', \'list\'])\ndef test_missing_shared_database_is_never_created(native_storage, verb):\n    private, _, _ = native_storage\n    assert REMINDER.is_file(), \'native regression requires the staged schedule-reminder CLI\'\n    missing = private / \'missing-shared.db\'\n    client = dedup.LedgerClient(cmd=[sys.executable, \'-B\', str(REMINDER)],\n                                db_path=str(missing), product_id=\'synthetic-product\')\n    with pytest.raises(ValueError, match=\'existing\'):\n        client._run(verb, [])\n    assert not missing.exists()\n\n\ndef test_explicitly_initialized_shared_database_remains_usable(native_storage):\n    private, _, _ = native_storage\n    assert REMINDER.is_file(), \'native regression requires the staged schedule-reminder CLI\'\n    db = private / \'existing-shared.db\'\n    command = [sys.executable, \'-B\', str(REMINDER)]\n    initialized = subprocess.run([*command, \'--db\', str(db), \'init\'],\n                                 capture_output=True, text=True, check=True)\n    assert json.loads(initialized.stdout)[\'ok\'] is True and db.stat().st_size > 0\n    client = dedup.LedgerClient(cmd=command, db_path=str(db), product_id=\'synthetic-product\')\n    assert client.init()[\'ok\'] is True\n    assert client.list_active() == []\n\n\ndef test_private_log_cannot_append_through_hardlink_to_public_file(native_storage):\n    private, public, _ = native_storage\n    original = public / \'published.txt\'\n    original.write_text(\'synthetic public fixture\\n\', encoding=\'utf-8\')\n    alias = private / \'daemon.log\'\n    os.link(original, alias)\n    before = original.read_bytes()\n    assert alias.stat().st_nlink == 2\n    with pytest.raises(PrivateLogError):\n        with PrivateLog(alias) as stream:\n            stream.write(\'synthetic runtime observation\\n\')\n    assert original.read_bytes() == before\n\n\ndef test_plain_private_log_still_appends(native_storage):\n    private, _, _ = native_storage\n    log = private / \'daemon.log\'\n    with PrivateLog(log) as stream:\n        stream.write(\'synthetic first\\n\')\n        stream.write(\'synthetic second\\n\')\n    assert log.read_text(encoding=\'utf-8\') == \'synthetic first\\nsynthetic second\\n\'\n\n\ndef test_repeated_atomic_write_supports_a_long_data_path(native_storage):\n    private, _, _ = native_storage\n    directory = private\n    while len(str(directory/\'state.json\')) < 321:\n        directory = directory / (\'a\' * 60)\n    target = directory / \'state.json\'\n    assert len(str(target)) >= 321\n    data_safety.atomic_json(target, {\'synthetic_attempt\': 1})\n    data_safety.atomic_json(target, {\'synthetic_attempt\': 2})\n    assert json.loads(target.read_text(encoding=\'utf-8\')) == {\'synthetic_attempt\': 2}\n\n\n@pytest.mark.parametrize(\'visibility\', [\'PUBLIC\', \'PRIVATE\'])\ndef test_nearest_nested_repository_remains_authoritative(native_storage, visibility):\n    private, _, repository = native_storage\n    nested = repository(private/\'nested\', \'nested-vault\', visibility)\n    target = nested/\'deep/state.json\'\n    if visibility == \'PUBLIC\':\n        with pytest.raises(data_safety.DestinationError):\n            data_safety.atomic_json(target, {\'synthetic\': True})\n        assert not target.exists()\n    else:\n        data_safety.atomic_json(target, {\'synthetic\': True})\n        proof = data_safety.require_private(target)\n        assert Path(proof[\'root\']) == nested\n        assert proof[\'repository\'] == \'example-owner/nested-vault\'\n\n\ndef junction(target, alias):\n    if os.name == "nt":\n        import _winapi\n        _winapi.CreateJunction(str(target), str(alias))\n    else:\n        alias.symlink_to(target, target_is_directory=True)\n\n\n@pytest.mark.parametrize("verb", ["init", "list"])\ndef test_empty_database_is_not_an_initialized_shared_store(native_storage, verb):\n    private, _, _ = native_storage\n    database = private / "empty.db"\n    database.touch()\n    client = dedup.LedgerClient(cmd=[sys.executable, "-B", str(REMINDER)], db_path=str(database))\n    with pytest.raises(ValueError, match="existing"):\n        client._run(verb, [])\n    assert database.stat().st_size == 0\n\n\ndef test_private_directory_alias_is_refused(native_storage):\n    private, _, _ = native_storage\n    target = private / "actual"\n    target.mkdir()\n    alias = private / "alias"\n    junction(target, alias)\n    with pytest.raises(data_safety.DestinationError):\n        data_safety.atomic_json(alias / "state.json", {"synthetic": True})\n    assert not (target / "state.json").exists()\n    with pytest.raises(data_safety.DestinationError):\n        data_safety.require_private_push(alias, "example-owner/private-vault")\n\n\ndef test_dangling_git_boundary_cannot_fall_back_to_outer_private_repo(native_storage):\n    private, _, _ = native_storage\n    nested = private / "nested"\n    nested.mkdir()\n    target = private / "temporary-admin"\n    target.mkdir()\n    junction(target, nested / ".git")\n    target.rmdir()\n    with pytest.raises(data_safety.DestinationError):\n        data_safety.atomic_json(nested / "state.json", {"synthetic": True})\n    assert not (nested / "state.json").exists()\n'


def storage_updated_test_sources():
    return {'test_run_contract.py': '"""Deterministic regression tests at isolated model, receipt and Git boundaries."""\nimport copy\nimport hashlib\nimport json\nfrom pathlib import Path\nimport subprocess\nimport importlib.util\nimport sys\nimport types\n\nimport pytest\n\nimport data_safety\nimport lib\nimport push_card\nimport redact\nimport run\n\n\n@pytest.fixture\ndef cases():\n    return json.loads((Path(__file__).parent / "fixtures/repair_cases.json").read_text())\n\n\n@pytest.fixture\ndef private_repo(tmp_path, monkeypatch):\n    root = tmp_path / "companion"\n    root.mkdir()\n    (root / ".git").mkdir()\n    def synthetic_git(directory, *args, **kwargs):\n        if args == ("rev-parse", "--show-toplevel"):\n            stdout = str(root)\n        elif args == ("config", "--null", "--list"):\n            stdout = ""\n        elif args in {("remote", "get-url", "origin"),\n                       ("remote", "get-url", "--all", "origin"),\n                       ("remote", "get-url", "--all", "--push", "origin")}:\n            stdout = "https://github.com/example/demand-mining-config.git"\n        else:\n            raise AssertionError("unapproved synthetic Git command")\n        return subprocess.CompletedProcess(["git", *args], 0, stdout=stdout, stderr="")\n\n    monkeypatch.setattr(data_safety, "git", synthetic_git)\n    monkeypatch.setattr(data_safety, "_companion_proof", lambda directory: types.SimpleNamespace(\n        root=str(root), repositories=("example/demand-mining-config",), signature="synthetic-proof"))\n    monkeypatch.setenv("DEMAND_MINING_CONFIG", str(root))\n    monkeypatch.delenv("DEMAND_MINING_DRYRUN", raising=False)\n    # Default deny of the external send seam, including before a failing assertion.\n    monkeypatch.setattr(push_card, "deliver", lambda message, dry_run=False: (False, "synthetic blocked"))\n    return root\n\n\n@pytest.fixture\ndef cfg():\n    result = copy.deepcopy(lib.DEFAULT_CONFIG)\n    result.update(product_id="example-product", timezone="America/New_York")\n    return result\n\n\nclass Ledger:\n    def __init__(self):\n        self.rows = []\n        self.watermarks = []\n\n    def list_active(self):\n        return self.rows\n\n    def upsert(self, card, ext, priority=0):\n        self.rows.append({"idempotency_key": "demand-mining:" + card["canonical_key"], "ext": ext})\n\n    def _run(self, verb, args):\n        return {"ok": True}\n\n    def add_watermark(self, value):\n        self.watermarks.append(value)\n\n\ndef test_person_and_address_are_removed_before_output(cases):\n    result = redact.redact(cases["private_text"])\n    assert cases["person"] not in result["redacted"]\n    assert cases["address"] not in result["redacted"]\n    assert redact.redact(cases["product_text"])["redacted"] == cases["product_text"]\n\n\ndef test_explicit_invalid_config_does_not_fall_back(tmp_path, monkeypatch):\n    missing = tmp_path / "missing"\n    monkeypatch.setenv("DEMAND_MINING_CONFIG", str(missing))\n    with pytest.raises(ValueError, match="DEMAND_MINING_CONFIG"):\n        lib.find_config_dir()\n\n\ndef test_nonprivate_destination_is_named(private_repo, monkeypatch):\n    def refuse(directory):\n        raise data_safety.DestinationError("synthetic PUBLIC companion")\n    monkeypatch.setattr(data_safety, "_companion_proof", refuse)\n    with pytest.raises(data_safety.DestinationError, match="PUBLIC") as error:\n        data_safety.atomic_json(private_repo / "pool/result.json", {})\n    assert str(private_repo) in str(error.value)\n    assert not (private_repo / "pool").exists()\n\n\ndef test_ledger_failure_is_not_empty_success(private_repo, cfg, cases):\n    ledger = Ledger()\n    ledger.list_active = lambda: (_ for _ in ()).throw(RuntimeError("ledger unavailable"))\n    with pytest.raises(RuntimeError, match="ledger unavailable"):\n        run.process([cases["candidate"]], cfg, ledger, archive_dir=str(private_repo / "pool"))\n    assert not ledger.watermarks\n\n\ndef test_confirmed_receipt_is_required_for_watermark(private_repo, cfg, cases, monkeypatch):\n    ledger = Ledger()\n    monkeypatch.setattr(push_card, "deliver", lambda message, dry_run=False: (True, "exit zero only"))\n    result = run.process([cases["candidate"]], cfg, ledger, archive_dir=str(private_repo / "pool"))\n    assert result["status"] == "pending_reconciliation"\n    assert not ledger.watermarks\n\n\ndef test_delivery_replay_has_same_artifacts_and_does_not_resend(private_repo, cfg, cases, monkeypatch):\n    ledger, sent = Ledger(), []\n\n    def deliver(message, dry_run=False):\n        sent.append(message)\n        return True, {"status": "confirmed", "message_id": "synthetic-receipt",\n                      "identity": push_card._DELIVERY_IDENTITY.get(),\n                      "content_sha256": hashlib.sha256(message.encode()).hexdigest()}\n\n    monkeypatch.setattr(push_card, "deliver", deliver)\n    result = run.process([cases["candidate"]], cfg, ledger, archive_dir=str(private_repo / "pool"))\n    assert result["status"] == "complete"\n    replay = run.process([cases["candidate"]], cfg, ledger, archive_dir=str(private_repo / "pool"))\n    assert replay["status"] == "complete"\n    assert len(sent) == 1\n    assert len(ledger.watermarks) == 1\n    manifest = json.loads(Path(result["manifest_path"]).read_text(encoding="utf-8"))\n    assert manifest["identity"]["timezone"] == "America/New_York"\n    for artifact in manifest["artifacts"]:\n        content = Path(artifact["path"]).read_bytes()\n        assert hashlib.sha256(content).hexdigest() == artifact["sha256"]\n        assert len(content) == artifact["bytes"]\n\n\ndef test_unknown_delivery_never_automatically_resends(private_repo, cfg, cases, monkeypatch):\n    ledger, calls = Ledger(), []\n\n    def deliver(message, dry_run=False):\n        calls.append(message)\n        raise TimeoutError("ambiguous transport")\n\n    monkeypatch.setattr(push_card, "deliver", deliver)\n    first = run.process([cases["candidate"]], cfg, ledger, archive_dir=str(private_repo / "pool"))\n    second = run.process([cases["candidate"]], cfg, ledger, archive_dir=str(private_repo / "pool"))\n    assert first["status"] == second["status"] == "pending_reconciliation"\n    assert len(calls) == 1\n    assert not ledger.watermarks\n\n\ndef test_empty_input_without_collection_evidence_cannot_complete(private_repo, cfg):\n    with pytest.raises(ValueError, match="collection"):\n        run.process([], cfg, Ledger(), archive_dir=str(private_repo / "pool"))\n\n\ndef _confirm(message, dry_run=False):\n    return True, {"status": "confirmed", "message_id": "synthetic-receipt",\n                  "identity": push_card._DELIVERY_IDENTITY.get(),\n                  "content_sha256": hashlib.sha256(message.encode()).hexdigest()}\n\n\ndef test_changed_artifact_blocks_replay(private_repo, cfg, cases, monkeypatch):\n    monkeypatch.setattr(push_card, "deliver", _confirm)\n    ledger = Ledger()\n    first = run.process([cases["candidate"]], cfg, ledger, archive_dir=str(private_repo / "pool"))\n    Path(first["digest_path"]).write_text("synthetic changed bytes", encoding="utf-8")\n    with pytest.raises(ValueError, match="artifact bytes differ"):\n        run.process([cases["candidate"]], cfg, ledger, archive_dir=str(private_repo / "pool"))\n\n\ndef test_watermark_failure_retries_without_delivery(private_repo, cfg, cases, monkeypatch):\n    calls = []\n    monkeypatch.setattr(push_card, "deliver", lambda message, dry_run=False: (calls.append(message), _confirm(message))[1])\n    ledger = Ledger()\n    ledger.add_watermark = lambda value: (_ for _ in ()).throw(OSError("synthetic watermark failure"))\n    with pytest.raises(OSError, match="synthetic watermark"):\n        run.process([cases["candidate"]], cfg, ledger, archive_dir=str(private_repo / "pool"))\n    ledger.add_watermark = lambda value: ledger.watermarks.append(value)\n    assert run.process([cases["candidate"]], cfg, ledger, archive_dir=str(private_repo / "pool"))["ok"]\n    assert len(calls) == 1\n\n\ndef test_receipt_without_identity_is_unknown(private_repo, cfg, cases, monkeypatch):\n    def unbound(message, dry_run=False):\n        ok, receipt = _confirm(message)\n        receipt.pop("identity")\n        return ok, receipt\n\n    monkeypatch.setattr(push_card, "deliver", unbound)\n    ledger = Ledger()\n    result = run.process([cases["candidate"]], cfg, ledger, archive_dir=str(private_repo / "pool"))\n    assert result["status"] == "pending_reconciliation"\n    assert not ledger.watermarks\n\n\ndef test_saved_identity_survives_midnight(cfg, monkeypatch):\n    from finalize import logical_identity\n    monkeypatch.setenv("DEMAND_MINING_NOW", "2026-03-08T06:30:00Z")\n    identity = logical_identity(cfg)\n    monkeypatch.setenv("DEMAND_MINING_NOW", "2026-03-09T06:30:00Z")\n    assert logical_identity(cfg, identity) == identity\n    assert identity["source_window"]["end"] == "2026-03-08T06:30:00Z"\n\n\ndef test_pseudonym_metadata_cannot_bypass_privacy(cases):\n    forged = "u_" + cases["person"].lower().replace(" ", "_")\n    result = redact.safe_data({"author_hash": forged})\n    assert "example" not in result["author_hash"]\n    assert "user_id" not in result\n    with pytest.raises(ValueError, match="conflicting author identity"):\n        redact.safe_data({"author_hash": forged, "user_id": 123})\n\n\ndef test_overlapping_callers_finish_once(private_repo, cfg, cases, monkeypatch):\n    from concurrent.futures import ThreadPoolExecutor\n    calls = []\n    mkdir = data_safety.os.mkdir\n    attempted = []\n\n    def traced_mkdir(path, *args, **kwargs):\n        attempted.append(str(path))\n        return mkdir(path, *args, **kwargs)\n\n    monkeypatch.setattr(data_safety.os, "mkdir", traced_mkdir)\n    monkeypatch.setattr(push_card, "deliver", lambda message, dry_run=False: (calls.append(message), _confirm(message))[1])\n    ledger = Ledger()\n    try:\n        with ThreadPoolExecutor(max_workers=2) as pool:\n            results = list(pool.map(lambda _: run.process([cases["candidate"]], cfg, ledger,\n                                   archive_dir=str(private_repo / "pool")), range(2)))\n    except Exception:\n        print("synthetic mkdir attempts: " + json.dumps(attempted))\n        raise\n    assert all(result["status"] == "complete" for result in results)\n    assert len(calls) == 1\n\n\n@pytest.mark.parametrize("seeded", [False, True])\ndef test_file_lock_excludes_contender_and_releases_after_exception(private_repo, seeded):\n    path = private_repo / "exclusive.lock"\n    if seeded:\n        path.write_bytes(b"0")\n    with pytest.raises(ValueError, match="synthetic owner failure"):\n        with data_safety.file_lock(path):\n            with pytest.raises(TimeoutError, match="DATA lock unavailable"):\n                with data_safety.file_lock(path, timeout=0.1):\n                    pytest.fail("a contender acquired the owned lock")\n            raise ValueError("synthetic owner failure")\n    with data_safety.file_lock(path, timeout=0.1):\n        pass\n\n\n@pytest.fixture\ndef service_cases():\n    path = Path(__file__).resolve().parents[3] / "tools/make_fixtures.py"\n    spec = importlib.util.spec_from_file_location("synthetic_fixture_generator", path)\n    module = importlib.util.module_from_spec(spec)\n    spec.loader.exec_module(module)\n    return module.fixtures()\n\n\ndef test_generator_reproduces_committed_fixture(service_cases, tmp_path):\n    # Keep the newly generated output in synthetic OUT for an explicit source copy.\n    content = json.dumps(service_cases, indent=2, sort_keys=True) + "\\n"\n    (tmp_path / "repair_cases.json").write_text(content, encoding="utf-8")\n    path = Path(__file__).parent / "fixtures/repair_cases.json"\n    assert path.read_text(encoding="utf-8") == content\n\n\ndef test_git_failure_is_visible_and_optional_locks_cannot_be_enabled(tmp_path, monkeypatch):\n    calls = []\n\n    def child(argv, **kwargs):\n        calls.append((argv, kwargs))\n        return subprocess.CompletedProcess(argv, 17, stdout="", stderr="synthetic private detail")\n\n    monkeypatch.setattr(data_safety.subprocess, "run", child)\n    with pytest.raises(RuntimeError, match="exit 17") as error:\n        data_safety.git(tmp_path, "status", env={"GIT_OPTIONAL_LOCKS": "1"})\n    assert "synthetic private detail" not in str(error.value)\n    assert calls[0][1]["env"]["GIT_OPTIONAL_LOCKS"] == "0"\n\n\n@pytest.mark.parametrize("verb", ["read-tree", "add", "diff", "commit", "push"])\ndef test_backup_failure_stops_later_steps(private_repo, monkeypatch, verb):\n    import backup\n    path = private_repo / "synthetic-result.json"\n    path.write_text("{}", encoding="utf-8")\n    calls = []\n\n    def git(directory, *args, **kwargs):\n        calls.append((args[0], kwargs))\n        if args[0] == verb:\n            raise RuntimeError("synthetic " + verb + " failure")\n        return subprocess.CompletedProcess(["git", *args], 1 if args[0] == "diff" else 0,\n                                           stdout="", stderr="")\n\n    monkeypatch.setattr(backup, "git", git)\n    monkeypatch.setattr(backup, "require_private_push", lambda *args: None)\n    with pytest.raises(RuntimeError, match="synthetic " + verb):\n        backup.backup([path])\n    stages = ["read-tree", "add", "diff", "commit", "push"]\n    assert [item[0] for item in calls] == stages[:stages.index(verb) + 1]\n    for stage, kwargs in calls:\n        if stage == "diff":\n            assert kwargs["env"]["GIT_INDEX_FILE"]\n        assert kwargs["env"].get("GIT_LITERAL_PATHSPECS") == "1"\n\n\ndef test_backup_rejects_directory_pathspec(private_repo):\n    import backup\n    with pytest.raises(ValueError, match="regular file"):\n        backup.backup([private_repo])\n\n\ndef test_effective_push_url_cannot_point_to_another_repository(private_repo, monkeypatch):\n    def wrong_push(directory, *args, **kwargs):\n        if args == ("rev-parse", "--show-toplevel"):\n            output = str(private_repo)\n        elif args == ("config", "--null", "--list"):\n            output = ""\n        elif args[:2] == ("remote", "get-url"):\n            output = ("https://github.com/example/other-config.git" if "--push" in args else\n                      "https://github.com/example/demand-mining-config.git")\n        else:\n            raise AssertionError("unapproved synthetic Git command")\n        return subprocess.CompletedProcess([], 0, stdout=output, stderr="")\n    monkeypatch.setattr(data_safety, "git", wrong_push)\n    with pytest.raises(data_safety.DestinationError, match="attested companion routes"):\n        data_safety.require_private_push(private_repo, "example/demand-mining-config")\n\n\ndef test_confirmed_push_bookkeeping_is_idempotent(private_repo, cfg, cases, monkeypatch):\n    import dedup\n    monkeypatch.setattr(push_card, "deliver", _confirm)\n    ledger = Ledger()\n    for _ in range(2):\n        result = run.process([cases["candidate"]], cfg, ledger, archive_dir=str(private_repo / "pool"))\n        assert result["pushed"]\n    assert ledger.rows[-1]["ext"][dedup.EXT + "push_count"] == 1\n\n\ndef test_reconciliation_finishes_without_resend(private_repo, cfg, cases, monkeypatch):\n    import finalize\n    ledger = Ledger()\n    first = run.process([cases["candidate"]], cfg, ledger, archive_dir=str(private_repo / "pool"))\n    manifest = json.loads(Path(first["manifest_path"]).read_text(encoding="utf-8"))\n    receipt = {"status": "confirmed", "identity": first["identity"],\n               "content_sha256": manifest["content_sha256"], "message_id": "synthetic-reconciled"}\n    finalize.reconcile(first["state_path"], receipt)\n    monkeypatch.setattr(push_card, "deliver", lambda *a, **k: pytest.fail("unexpected resend"))\n    second = run.process([cases["candidate"]], cfg, ledger, archive_dir=str(private_repo / "pool"))\n    assert second["status"] == "complete"\n    assert len(ledger.watermarks) == 1\n\n\ndef test_explicit_empty_completion_keeps_collection_evidence(private_repo, cfg, monkeypatch):\n    import finalize\n    identity = finalize.logical_identity(cfg)\n    handoff = {"identity": identity, "candidates": [], "collection": {\n        "status": "complete", "classification": "complete", "source_window": identity["source_window"]}}\n    monkeypatch.setattr(push_card, "deliver", _confirm)\n    result = run.process(handoff, cfg, Ledger(), archive_dir=str(private_repo / "pool"))\n    assert result["status"] == "complete" and result["empty_day"]\n    assert not result["pushed"]\n\n\ndef test_scheduled_proposal_uses_shared_agent_interface(cfg, cases, monkeypatch):\n    import scheduled\n    import llmcall\n    calls = []\n\n    def call(prompt, **kwargs):\n        calls.append((prompt, kwargs))\n        return types.SimpleNamespace(error=None, data={"classification": "complete",\n                                                     "candidates": [cases["candidate"]]})\n\n    monkeypatch.setattr(llmcall, "call", call)\n    evidence = cases["candidate"]["evidence"][0]\n    corpus = {"channels": {"feedback": [{\n        "text": cases["private_text"] + " " + cases["product_text"],\n        "ts": evidence["ts"], "author_hash": redact.pseudonymize(cases["person"])}]}}\n    proposed = scheduled.propose(corpus, cfg)\n    assert proposed and proposed[0]["observation_provenance"] == "collected_corpus"\n    assert calls[0][1] == {"mode": "agent"}\n    assert cases["person"] not in calls[0][0] and cases["address"] not in calls[0][0]\n    assert cases["product_text"] in calls[0][0]\n\n\ndef test_scheduled_retry_reuses_handoff_and_delivery_then_continues_cutoff(private_repo, cfg, cases, monkeypatch):\n    import backup\n    import scheduled\n    windows, sends, backups = [], [], []\n    ledger = Ledger()\n    ledger.init = lambda: None\n    monkeypatch.setattr(scheduled, "preflight", lambda *a: (\n        cfg, private_repo, private_repo / "pool", private_repo / "logs"))\n    monkeypatch.setattr(scheduled.pull_discord, "_load_wiring", lambda: ([], "synthetic-token"))\n\n    def collect(channels, token, source_window):\n        windows.append(source_window)\n        return {"collection": {"status": "complete", "source_window": source_window}}\n\n    def save(paths):\n        backups.append(paths)\n        if len(backups) == 1:\n            raise RuntimeError("synthetic backup failure")\n        return {"status": "confirmed"}\n\n    monkeypatch.setattr(scheduled.pull_discord, "pull", collect)\n    monkeypatch.setattr(scheduled, "propose", lambda *a: [cases["candidate"]])\n    monkeypatch.setattr(scheduled.dedup, "LedgerClient", lambda **k: ledger)\n    monkeypatch.setattr(backup, "backup", save)\n    monkeypatch.setattr(push_card, "deliver", lambda message, dry_run=False: (\n        sends.append(message), _confirm(message))[1])\n    monkeypatch.setenv("DEMAND_MINING_NOW", "2026-03-08T06:30:00Z")\n    first = scheduled.execute()\n    assert first["status"] == "delivered_backup_pending"\n    monkeypatch.setenv("DEMAND_MINING_NOW", "2026-03-09T06:30:00Z")\n    second = scheduled.execute()\n    assert second["status"] == "complete" and len(sends) == 1 and len(windows) == 1\n    assert first["identity"] == second["identity"]\n    third = scheduled.execute()\n    assert third["status"] == "complete" and len(windows) == 2\n    assert windows[1]["start"] == windows[0]["end"]\n\n\n@pytest.fixture\ndef bot_module(monkeypatch):\n    # Load only the product module; no Discord client, sockets or event loop exists.\n    fake = types.ModuleType("discord")\n    fake.Client = type("Client", (), {})\n    fake.Thread = type("Thread", (), {})\n    fake.Message = type("Message", (), {})\n    monkeypatch.setitem(sys.modules, "discord", fake)\n    path = Path(__file__).resolve().parents[1] / "scripts/demand_bot.py"\n    spec = importlib.util.spec_from_file_location("contract_bot", path)\n    module = importlib.util.module_from_spec(spec)\n    spec.loader.exec_module(module)\n    return module\n\n\ndef test_bot_wiring_selects_configured_product(private_repo, cfg, service_cases, monkeypatch, bot_module):\n    (private_repo / "registry.json").write_text(json.dumps(service_cases["registry"]), encoding="utf-8")\n    (private_repo / "synthetic-selected-token.txt").write_text("synthetic-token", encoding="utf-8")\n    monkeypatch.setattr(bot_module, "load_config", lambda: cfg)\n    token, channels, _, _, product = bot_module._wiring(private_repo)\n    assert token == "synthetic-token" and channels == {"2": "feedback"}\n    assert product == "CSV export"\n\n\n@pytest.mark.parametrize("field,value", [("is_demand", "false"), ("confidence", 2.0),\n                                        ("confidence", float("nan")), ("title", []),\n                                        ("track", None), ("kano", "unknown")])\ndef test_invalid_classification_is_visible(bot_module, service_cases, monkeypatch, field, value):\n    verdict = dict(service_cases["verdict"], **{field: value})\n    monkeypatch.setattr(bot_module, "_llm", lambda *a, **k: ([verdict], "synthetic-provider"))\n    with pytest.raises(ValueError, match="classification"):\n        bot_module.classify_batch([{"i": 0, "channel": "feedback", "text": service_cases["product_text"]}])\n\n\ndef test_bot_classification_audit_and_reply_scrub_all_model_boundaries(bot_module, service_cases, monkeypatch):\n    calls = []\n    verdict = dict(service_cases["verdict"], why=service_cases["private_text"])\n\n    def call(prompt, **kwargs):\n        calls.append((prompt, kwargs))\n        return types.SimpleNamespace(error=None, data=[verdict], text=service_cases["private_text"],\n                                     provider="synthetic-provider")\n\n    monkeypatch.setattr(bot_module, "_llmcall", call)\n    results = bot_module.classify_batch([{"i": 0, "channel": "feedback",\n                                         "text": service_cases["private_text"]}])\n    reply = bot_module.gen_reply(service_cases["private_text"], context=service_cases["private_text"])\n    assert len(calls) == 3\n    assert set(calls[0][1]) == {"schema"}\n    assert calls[1][1]["avoid"] == "synthetic-provider"\n    assert not calls[2][1]\n    for text in [json.dumps(results), reply, *(item[0] for item in calls)]:\n        assert service_cases["person"] not in text and service_cases["address"] not in text\n\n\n@pytest.mark.parametrize("response", [{}, "FORBIDDEN"])\ndef test_collection_errors_do_not_become_empty_success(service_cases, monkeypatch, response):\n    import pull_discord\n    monkeypatch.setattr(pull_discord, "_get", lambda *a: response)\n    with pytest.raises((ValueError, RuntimeError)):\n        pull_discord.pull(service_cases["registry"]["products"][0]["discord_channels"], "synthetic-token")\n\n\ndef test_collection_requires_a_declared_source():\n    import pull_discord\n    with pytest.raises(ValueError, match="source"):\n        pull_discord.pull([], "synthetic-token")\n\n\ndef test_collection_preserves_distinct_redacted_channels(service_cases, monkeypatch):\n    import pull_discord\n    channels = [{"id": "1", "name": service_cases["person"]},\n                {"id": "2", "name": service_cases["person"]}]\n    message = dict(service_cases["message"], content=service_cases["private_text"])\n    monkeypatch.setattr(pull_discord, "_get", lambda *a: [message])\n    result = pull_discord.pull(channels, "synthetic-token", full=True)\n    assert len(result["channels"]) == 2\n    text = json.dumps(result)\n    assert service_cases["person"] not in text and service_cases["address"] not in text\n\n\n@pytest.mark.parametrize("response", ["", "[]", \'{"ok": false}\', \'{"error": "synthetic failure"}\'])\ndef test_ledger_rejects_failed_or_missing_response(private_repo, monkeypatch, response):\n    import dedup\n    database = private_repo / "synthetic.db"\n    database.write_bytes(b"synthetic existing store")\n    ledger = dedup.LedgerClient(cmd=["synthetic-ledger"], db_path=str(database))\n    monkeypatch.setattr(dedup.subprocess, "run", lambda *a, **k: subprocess.CompletedProcess(\n        [], 0, stdout=response, stderr=""))\n    with pytest.raises(ValueError, match="reminder.py"):\n        ledger.init()\n\n\ndef test_ledger_cannot_hide_missing_rows_or_repeat_cursor(monkeypatch):\n    import dedup\n    ledger = dedup.LedgerClient(cmd=["synthetic-ledger"])\n    monkeypatch.setattr(ledger, "_run", lambda *a: {})\n    with pytest.raises(ValueError, match="items array"):\n        ledger.list_active()\n    monkeypatch.setattr(ledger, "_run", lambda *a: {"items": [], "next_cursor": "synthetic-cursor"})\n    with pytest.raises(ValueError, match="cursor"):\n        ledger.list_active()\n\n\ndef _complete_pure_coroutine(coroutine):\n    # These doubles complete synchronously at await points, requiring no socket-\n    # backed asyncio event loop and no external work.\n    try:\n        coroutine.send(None)\n    except StopIteration as stopped:\n        return stopped.value\n    finally:\n        coroutine.close()\n    raise AssertionError("test coroutine unexpectedly requested external scheduling")\n\n\ndef test_bot_context_privacy_is_checked_before_return(bot_module, service_cases):\n    bot = bot_module.DemandBot.__new__(bot_module.DemandBot)\n    bot.user = None\n    bot.log = lambda message: None\n    channel = bot_module.discord.Thread()\n    channel.name = service_cases["private_text"]\n    channel.starter_message = types.SimpleNamespace(id=1, content=service_cases["private_text"])\n\n    async def history(**kwargs):\n        yield types.SimpleNamespace(author=types.SimpleNamespace(id=42, bot=False),\n                                    content=service_cases["private_text"])\n\n    channel.history = history\n    message = types.SimpleNamespace(id=2, channel=channel, reference=None)\n    context = _complete_pure_coroutine(bot._gather_context(message))\n    assert service_cases["person"] not in context and service_cases["address"] not in context\n    assert "CSV export" in context\n\n\ndef test_bot_daily_summary_unknown_send_is_reconcilable(private_repo, cfg, bot_module):\n    bot = bot_module.DemandBot.__new__(bot_module.DemandBot)\n    bot.cfg, bot.poolp = cfg, str(private_repo / "demands.jsonl")\n    bot.post_display, bot.display_id, bot.summary_hour = True, 2, 0\n    bot.get_channel = lambda channel_id: object()\n    bot.log = lambda message: None\n    bot._render_summary = lambda today: "CSV export needs retry support."\n    sends = []\n\n    async def send(today, body=None, channel=None):\n        sends.append(body)\n        raise TimeoutError("synthetic ambiguous delivery")\n\n    bot._post_daily_summary = send\n    assert _complete_pure_coroutine(bot._maybe_daily_summary())["status"] == "pending_reconciliation"\n    assert _complete_pure_coroutine(bot._maybe_daily_summary())["status"] == "pending_reconciliation"\n    assert len(sends) == 1\n    state = json.loads(Path(bot._summary_marker()).read_text(encoding="utf-8"))\n    bot.reconcile_daily_summary({"identity": state["identity"], "status": "confirmed",\n                                 "message_id": "synthetic-message", "content_sha256": state["content_sha256"]})\n    assert _complete_pure_coroutine(bot._maybe_daily_summary())["status"] == "confirmed"\n    assert len(sends) == 1\n\n\ndef test_bot_summary_groups_timestamps_by_configured_local_day(private_repo, cfg, bot_module, monkeypatch):\n    bot = bot_module.DemandBot.__new__(bot_module.DemandBot)\n    bot.cfg, bot.poolp = cfg, str(private_repo / "demands.jsonl")\n    row = {"title": "CSV export", "last_seen": "2026-03-09T01:30:00Z"}\n    monkeypatch.setattr(bot_module.pool, "load", lambda path, *, product_id: [row])\n    monkeypatch.setattr(bot_module.pool, "ranked", lambda path, *, product_id: [row])\n    assert "Touched today: 1" in bot._render_summary("2026-03-08")\n    assert "Touched today: 0" in bot._render_summary("2026-03-09")\n\n\ndef test_direct_implicit_retry_freezes_cutoff_and_continues_next_day(private_repo, cfg, cases, monkeypatch):\n    calls = []\n    monkeypatch.setattr(push_card, "deliver", lambda message, dry_run=False: (\n        calls.append(message), _confirm(message))[1])\n    ledger = Ledger()\n    monkeypatch.setenv("DEMAND_MINING_NOW", "2026-03-08T06:30:00Z")\n    first = run.process([cases["candidate"]], cfg, ledger, archive_dir=str(private_repo / "pool"))\n    monkeypatch.setenv("DEMAND_MINING_NOW", "2026-03-08T07:30:00Z")\n    second = run.process([cases["candidate"]], cfg, ledger, archive_dir=str(private_repo / "pool"))\n    assert first["identity"] == second["identity"] and len(calls) == 1\n    monkeypatch.setenv("DEMAND_MINING_NOW", "2026-03-09T06:30:00Z")\n    third = run.process([cases["candidate"]], cfg, ledger, archive_dir=str(private_repo / "pool"))\n    assert third["identity"]["source_window"]["start"] == first["identity"]["source_window"]["end"]\n\n\ndef test_direct_implicit_failed_run_resumes_after_midnight(private_repo, cfg, cases, monkeypatch):\n    calls = []\n    monkeypatch.setattr(push_card, "deliver", lambda message, dry_run=False: (\n        calls.append(message), _confirm(message))[1])\n    ledger = Ledger()\n    original = ledger.add_watermark\n    ledger.add_watermark = lambda value: (_ for _ in ()).throw(OSError("synthetic interruption"))\n    monkeypatch.setenv("DEMAND_MINING_NOW", "2026-03-08T06:30:00Z")\n    with pytest.raises(OSError, match="synthetic interruption"):\n        run.process([cases["candidate"]], cfg, ledger, archive_dir=str(private_repo / "pool"))\n    ledger.add_watermark = original\n    monkeypatch.setenv("DEMAND_MINING_NOW", "2026-03-09T06:30:00Z")\n    resumed = run.process([cases["candidate"]], cfg, ledger, archive_dir=str(private_repo / "pool"))\n    assert resumed["status"] == "complete" and len(calls) == 1\n    assert resumed["identity"]["date"] == "2026-03-08"\n\n\ndef test_rejected_implicit_input_can_be_corrected(private_repo, cfg, cases, monkeypatch):\n    monkeypatch.setattr(push_card, "deliver", _confirm)\n    ledger = Ledger()\n    invalid = dict(cases["candidate"], evidence=[])\n    with pytest.raises(ValueError, match="candidate validation"):\n        run.process([invalid], cfg, ledger, archive_dir=str(private_repo / "pool"))\n    result = run.process([cases["candidate"]], cfg, ledger, archive_dir=str(private_repo / "pool"))\n    assert result["status"] == "complete"\n\n\ndef test_intervening_implicit_input_cannot_erase_an_earlier_receipt(private_repo, cfg, cases, monkeypatch):\n    calls = []\n    monkeypatch.setattr(push_card, "deliver", lambda message, dry_run=False: (\n        calls.append(message), _confirm(message))[1])\n    ledger = Ledger()\n    second_input = dict(cases["candidate"], recommendation="add bounded retries")\n    monkeypatch.setenv("DEMAND_MINING_NOW", "2026-03-08T06:30:00.100000Z")\n    first = run.process([cases["candidate"]], cfg, ledger, archive_dir=str(private_repo / "pool"))\n    monkeypatch.setenv("DEMAND_MINING_NOW", "2026-03-08T06:30:00.200000Z")\n    second = run.process([second_input], cfg, ledger, archive_dir=str(private_repo / "pool"))\n    monkeypatch.setenv("DEMAND_MINING_NOW", "2026-03-08T06:30:00.300000Z")\n    replay = run.process([cases["candidate"]], cfg, ledger, archive_dir=str(private_repo / "pool"))\n    assert replay["identity"] == first["identity"] and len(calls) == 2\n    pointer = json.loads(Path(replay["implicit_identity_path"]).read_text(encoding="utf-8"))\n    assert pointer["identity"] == second["identity"]\n\n\ndef test_summary_channel_absence_does_not_poison_delivery_state(private_repo, cfg, bot_module):\n    bot = bot_module.DemandBot.__new__(bot_module.DemandBot)\n    bot.cfg, bot.poolp = cfg, str(private_repo / "demands.jsonl")\n    bot.post_display, bot.display_id, bot.summary_hour = True, 2, 0\n    bot.log = lambda text: None\n    bot._render_summary = lambda day: "CSV export needs retries."\n    bot.get_channel = lambda channel_id: None\n    with pytest.raises(RuntimeError, match="before delivery"):\n        _complete_pure_coroutine(bot._maybe_daily_summary())\n    assert not Path(bot._summary_marker()).exists()\n    bot.get_channel = lambda channel_id: object()\n\n    async def send(today, body=None, channel=None):\n        return {"message_id": "synthetic-summary", "content_sha256": hashlib.sha256(body.encode()).hexdigest()}\n\n    bot._post_daily_summary = send\n    assert _complete_pure_coroutine(bot._maybe_daily_summary())["status"] == "confirmed"\n\n\ndef test_summary_accepts_slug_and_keeps_legacy_utc_hour(private_repo, cfg, bot_module, monkeypatch):\n    bot = bot_module.DemandBot.__new__(bot_module.DemandBot)\n    bot.cfg = {**cfg, "slug": cfg["product_id"]}\n    bot.cfg.pop("product_id")\n    bot.poolp = str(private_repo / "demands.jsonl")\n    bot.post_display, bot.display_id, bot.summary_hour = True, 2, 3\n    bot.summary_hour_uses_utc = True\n    bot.log = lambda text: None\n    bot._render_summary = lambda day: "CSV export needs retries."\n    bot.get_channel = lambda channel_id: object()\n\n    async def send(today, body=None, channel=None):\n        return {"message_id": "synthetic-summary", "content_sha256": hashlib.sha256(body.encode()).hexdigest()}\n\n    bot._post_daily_summary = send\n    monkeypatch.setenv("DEMAND_MINING_NOW", "2026-03-09T04:30:00Z")  # 00:30 in configured zone\n    assert _complete_pure_coroutine(bot._maybe_daily_summary())["status"] == "confirmed"\n\n\n@pytest.mark.parametrize("checkpoint_fault", [None, "failure", "interrupt"])\ndef test_scheduled_completion_snapshot_has_final_bytes(private_repo, cfg, cases, monkeypatch, checkpoint_fault):\n    import backup\n    import scheduled\n    ledger, calls, snapshots = Ledger(), [], []\n    ledger.init = lambda: None\n    monkeypatch.setattr(scheduled, "preflight", lambda *a: (\n        cfg, private_repo, private_repo / "pool", private_repo / "logs"))\n    monkeypatch.setattr(scheduled.pull_discord, "_load_wiring", lambda: ([], "synthetic-token"))\n    monkeypatch.setattr(scheduled.pull_discord, "pull", lambda channels, token, source_window: {\n        "collection": {"status": "complete", "source_window": source_window}})\n    monkeypatch.setattr(scheduled, "propose", lambda *a: [cases["candidate"]])\n    monkeypatch.setattr(scheduled.dedup, "LedgerClient", lambda **k: ledger)\n    monkeypatch.setattr(push_card, "deliver", lambda message, dry_run=False: (\n        calls.append(message), _confirm(message))[1])\n\n    def save(paths):\n        snapshots.append({str(path): Path(path).read_bytes() for path in paths})\n        if checkpoint_fault == "interrupt" and len(snapshots) == 2:\n            raise KeyboardInterrupt("synthetic abrupt caller interruption")\n        if checkpoint_fault == "failure" and len(snapshots) == 2:\n            raise RuntimeError("synthetic completion snapshot failure")\n        return {"status": "confirmed"}\n\n    monkeypatch.setattr(backup, "backup", save)\n    monkeypatch.setenv("DEMAND_MINING_NOW", "2026-03-08T06:30:00Z")\n    if checkpoint_fault == "interrupt":\n        with pytest.raises(KeyboardInterrupt, match="synthetic abrupt"):\n            scheduled.execute()\n        monkeypatch.setenv("DEMAND_MINING_NOW", "2026-03-09T06:30:00Z")\n        result = scheduled.execute()\n        assert result["identity"]["date"] == "2026-03-08"\n    else:\n        result = scheduled.execute()\n    if checkpoint_fault == "failure":\n        assert result["status"] == "delivered_backup_pending"\n        assert result["backup"]["delivery_snapshot"]["status"] == "confirmed"\n        result = scheduled.execute()\n    assert result["status"] == "complete" and len(calls) == 1\n    assert snapshots[-1] == {path: Path(path).read_bytes() for path in snapshots[-1]}\n    assert not list((private_repo / "pool/scheduled").glob("*/checkpoint-pending.json"))\n', 'test_review15_repairs.py': '"""Generated synthetic cases for the four Demand14 review findings."""\nimport ast\nimport copy\nimport json\nimport importlib.util\nimport datetime\nimport os\nfrom pathlib import Path\nimport re\nimport subprocess\nimport types\n\nimport pytest\nimport data_safety\nimport dedup\nimport finalize\nimport lib\nimport redact\n\n\nCASES = json.loads((Path(__file__).parent / "fixtures/repair_cases.json").read_text(encoding="utf-8"))\nREVIEW = CASES["review15"]\n\n\n@pytest.fixture\ndef transport(tmp_path, monkeypatch):\n    root = tmp_path / "companion"\n    root.mkdir()\n    profile = tmp_path / "profile"\n    profile.mkdir()\n    for key in list(os.environ):\n        if key.upper().startswith("GIT_"):\n            monkeypatch.delenv(key, raising=False)\n    monkeypatch.setenv("HOME", str(profile))\n    monkeypatch.setenv("USERPROFILE", str(profile))\n    if os.name == "nt":\n        monkeypatch.setenv("ProgramData", str(profile / "program-data"))\n        import ctypes\n        def profile_folder(window, folder, token, flags, buffer):\n            buffer.value = str(profile)\n            return 0\n        monkeypatch.setattr(ctypes.windll.shell32, "SHGetFolderPathW", profile_folder)\n    monkeypatch.setenv("GIT_CONFIG_GLOBAL", os.devnull)\n    monkeypatch.setenv("GIT_CONFIG_NOSYSTEM", "1")\n    clean_env = dict(os.environ)\n    subprocess.run(["git", "-C", str(root), "init", "-q"], check=True, capture_output=True)\n    base_config = (root / ".git/config").read_bytes()\n    state = {"url": REVIEW["transport"][0]["url"], "config": [], "calls": []}\n    receipt = profile / "visibility.json"\n    receipt.write_text(json.dumps({"_refreshed": datetime.datetime.now(datetime.timezone.utc).isoformat(),\n        "example/demand-mining-config": "PRIVATE", "example/other-config": "PRIVATE"}), encoding="utf-8")\n    api = data_safety._guard_api()\n\n    def companion(directory):\n        (root / ".git/config").write_bytes(base_config)\n        entries = [("remote.origin.url", state["url"]), *state["config"]]\n        if "push" in state:\n            entries.append(("remote.origin.pushurl", state["push"]))\n        for key, value in entries:\n            subprocess.run(["git", "-C", str(root), "config", "--add", key, value or ""],\n                           env=clean_env, check=True, capture_output=True)\n        return api.prove_private_companion(directory, visibility_map=receipt)\n\n    monkeypatch.setattr(data_safety, "_companion_proof", companion)\n    return root, state\n\n\n@pytest.mark.parametrize("case", REVIEW["transport"], ids=lambda case: case["name"])\ndef test_data_write_binds_effective_transport(transport, monkeypatch, case):\n    root, state = transport\n    state.update(copy.deepcopy(case))\n    for key, value in case["env"].items():\n        monkeypatch.setenv(key, value)\n    destination = root / "pool/result.json"\n    if case["allowed"]:\n        data_safety.atomic_json(destination, {"synthetic": True})\n        assert destination.is_file()\n    else:\n        with pytest.raises(data_safety.DestinationError):\n            data_safety.atomic_json(destination, {"synthetic": True})\n        assert not destination.parent.exists()\n\n\ndef test_push_rechecks_transport_after_admission(transport, monkeypatch):\n    root, state = transport\n    proof = data_safety.require_private(root / "record.json")\n    monkeypatch.setenv("GIT_SSL_NO_VERIFY", "1")\n    with pytest.raises(data_safety.DestinationError):\n        data_safety.require_private_push(root, proof["repository"])\n\n\n@pytest.mark.parametrize("mode", ["discovered", "explicit-config", "explicit-salt"])\ndef test_salt_discovery_matches_preflight_across_fresh_states(tmp_path, monkeypatch, mode):\n    directory = tmp_path / "config"\n    (directory / "secrets").mkdir(parents=True)\n    (directory / "secrets/pseudonym_hmac_salt").write_text(REVIEW["salt"], encoding="utf-8")\n    monkeypatch.delenv("DEMAND_MINING_CONFIG", raising=False)\n    monkeypatch.delenv("DEMAND_MINING_PSEUDONYM_SALT", raising=False)\n    monkeypatch.setattr(lib, "CONFIG_FALLBACKS", [str(directory)])\n    if mode == "explicit-config":\n        monkeypatch.setenv("DEMAND_MINING_CONFIG", str(directory))\n    elif mode == "explicit-salt":\n        monkeypatch.setenv("DEMAND_MINING_PSEUDONYM_SALT", REVIEW["salt"])\n    outputs = []\n    for byte in (b"a", b"b"):\n        monkeypatch.setattr(redact, "_EPHEMERAL_SALT", None)\n        monkeypatch.setattr(redact.os, "urandom", lambda size, value=byte: value * size)\n        redact.ensure_stable_salt()\n        outputs.append([redact.pseudonymize(user) for user in REVIEW["users"]])\n    assert outputs[0] == outputs[1]\n    assert len(set(outputs[0])) == len(REVIEW["users"])\n\n\n@pytest.mark.parametrize("value", ["", " ", "\\n\\t"])\ndef test_real_salt_preflight_refuses_blank_configured_bytes(tmp_path, monkeypatch, value):\n    directory = tmp_path / "config"\n    (directory / "secrets").mkdir(parents=True)\n    (directory / "secrets/pseudonym_hmac_salt").write_text(value, encoding="utf-8")\n    monkeypatch.setenv("DEMAND_MINING_CONFIG", str(directory))\n    monkeypatch.delenv("DEMAND_MINING_PSEUDONYM_SALT", raising=False)\n    monkeypatch.setattr(redact, "_EPHEMERAL_SALT", None)\n    with pytest.raises(ValueError):\n        redact.ensure_stable_salt()\n\n\ndef _ledger(store, product):\n    client = dedup.LedgerClient(cmd=["synthetic-reminder"])\n    client.run_identity = {"product_id": product, "date": "2026-01-17", "timezone": "UTC",\n                           "source_window": {"start": "2026-01-16T00:00:00Z", "end": "2026-01-17T00:00:00Z"}}\n\n    def call(verb, args):\n        if verb == "list":\n            return {"ok": True, "items": list(copy.deepcopy(store).values())}\n        assert verb == "add"\n        key = args[args.index("--idempotency-key") + 1]\n        row = {"idempotency_key": key, "source": dedup.SOURCE,\n               "ext": json.loads(args[args.index("--ext") + 1])}\n        store[key] = row\n        return {"ok": True, "item": row}\n    client._run = call\n    return client\n\n\ndef test_shared_ledger_keeps_products_and_watermarks_separate():\n    store = {}\n    clients = [_ledger(store, product) for product in REVIEW["products"]]\n    cfg = copy.deepcopy(lib.DEFAULT_CONFIG)\n    for index, client in enumerate(clients):\n        identity = client.run_identity\n        current = {**cfg, "product_id": identity["product_id"], "timezone": "UTC"}\n        plan = finalize._prepare([CASES["candidate"]], current, client, identity, "synthetic-run")\n        assert plan["result"]["new"] == 1\n        for mutation in plan["mutations"]:\n            ext = dict(mutation["ext"], **{dedup.EXT + "push_count": 1})\n            client.upsert(mutation["card"], ext)\n            client.upsert(mutation["card"], ext)\n        client.add_watermark("2026-01-" + str(17 + index) + "T00:00:00Z")\n    assert len(store) == 4\n    for index, client in enumerate(clients):\n        assert client.get_watermark() == "2026-01-" + str(17 + index) + "T00:00:00Z"\n        identity = client.run_identity\n        plan = finalize._prepare([CASES["candidate"]], {**cfg, "product_id": identity["product_id"], "timezone": "UTC"},\n                                 client, identity, "synthetic-replay")\n        assert plan["result"]["suppressed"] == 1\n        assert all(row["ext"][dedup.EXT + "identity"]["product_id"] == identity["product_id"]\n                   for row in client.list_active())\n\n\ndef test_unknown_legacy_rows_are_not_assigned_to_a_product():\n    cfg = {**copy.deepcopy(lib.DEFAULT_CONFIG), "product_id": REVIEW["products"][0], "timezone": "UTC"}\n    client = _ledger({}, cfg["product_id"])\n    first = finalize._prepare([CASES["candidate"]], cfg, client, client.run_identity, "synthetic-first")\n    mutation = first["mutations"][0]\n    legacy = {"idempotency_key": dedup.KEY_PREFIX + mutation["card"]["canonical_key"],\n              "ext": {key: value for key, value in mutation["ext"].items() if key != dedup.EXT + "identity"}}\n    legacy["ext"][dedup.EXT + "push_count"] = 1\n    client._run = lambda verb, args: {"ok": True, "items": [legacy]}\n    plan = finalize._prepare([CASES["candidate"]], cfg, client, client.run_identity, "synthetic-second")\n    assert plan["result"]["new"] == 1\n\n\ndef _bot_namespace():\n    # Execute the shipped class and demand conversion definitions without loading a gateway,\n    # provider SDK, event loop, thread or external agent.\n    path = Path(__file__).parents[1] / "scripts/demand_bot.py"\n    tree = ast.parse(path.read_text(encoding="utf-8"))\n    selected = [node for node in tree.body if (\n        isinstance(node, ast.ClassDef) and node.name == "DemandBot"\n        or isinstance(node, ast.FunctionDef) and node.name in {\n            "_demand_from_verdict", "_message_observation"})]\n    future = ast.ImportFrom(module="__future__", names=[ast.alias(name="annotations")], level=0)\n    scope = {"discord": types.SimpleNamespace(Client=object), "re": re, "_SIGNAL": re.compile("export"),\n             "safe_text": redact.safe_text, "safe_data": redact.safe_data,\n             "canonical_key": lib.canonical_key, "iso": lib.iso, "now_utc": lib.now_utc,\n             "merge_observations": lib.merge_observations,\n             "observation_identity": lib.observation_identity, "pseudonymize": redact.pseudonymize}\n    exec(compile(ast.fix_missing_locations(ast.Module(body=[future, *selected], type_ignores=[])),\n                 str(path), "exec"), scope)\n    return scope\n\n\ndef _run_coroutine(coroutine):\n    try:\n        coroutine.send(None)\n    except StopIteration as done:\n        return done.value\n    finally:\n        coroutine.close()\n    raise AssertionError("synthetic await unexpectedly yielded")\n\n\n@pytest.mark.parametrize("fault", ["none", "classifier", "second-upsert"])\ndef test_worker_retains_failed_batch_and_does_not_replay_completed_items(fault):\n    scope = _bot_namespace()\n    bot = object.__new__(scope["DemandBot"])\n    bot.cfg = {"product_id": REVIEW["products"][0], "timezone": "UTC"}\n    bot.buffer = [{**row, "m": row["id"]} for row in REVIEW["worker"]]\n    bot.interval, bot.classify_sys, bot.product, bot.classify_rounds = 1, "", "synthetic", 1\n    bot.poolp, bot.rescore, bot.lo = "synthetic-pool", None, 0.4\n    bot.is_closed = lambda: False\n    logs, writes, acknowledgments, classification_calls = [], [], [], []\n    bot.log = logs.append\n    attempts = {"sleep": 0, "upsert": 0}\n\n    class StopControl(BaseException):\n        pass\n\n    async def sleep(seconds):\n        attempts["sleep"] += 1\n        if attempts["sleep"] > 3:\n            raise StopControl()\n\n    async def to_thread(function, *args):\n        return function(*args)\n\n    def classify(items, *args):\n        classification_calls.append(copy.deepcopy(items))\n        if fault == "classifier" and len(classification_calls) == 1:\n            raise ValueError("synthetic classifier failure")\n        return [{**CASES["verdict"], "i": row["i"], "confidence": 0.9,\n                 "title": "export option " + str(row["i"])} for row in items]\n\n    def upsert(path, demand, rescore):\n        assert demand["product_id"] == bot.cfg["product_id"]\n        attempts["upsert"] += 1\n        if fault == "second-upsert" and attempts["upsert"] == 2:\n            raise OSError("synthetic pool failure")\n        writes.append(demand["evidence"][0]["redacted_snippet"])\n        return "merged", {"title": demand["title"], "reach": 1, "final_score": 1}\n\n    async def acknowledge(message, confidence):\n        acknowledgments.append(message)\n\n    async def note(message):\n        pass\n\n    scope.update(asyncio=types.SimpleNamespace(sleep=sleep, to_thread=to_thread),\n                 classify_batch=classify, pool=types.SimpleNamespace(upsert=upsert))\n    bot._ack, bot._note = acknowledge, note\n    try:\n        _run_coroutine(bot._classify_loop())\n    except StopControl:\n        pass\n    assert sorted(writes) == sorted(row["text"] for row in REVIEW["worker"])\n    assert sorted(acknowledgments) == sorted(row["id"] for row in REVIEW["worker"])\n    assert len(writes) == len(set(writes)) == 3\n    if fault != "none":\n        assert any("pending" in message or "retry" in message for message in logs)\n\n\ndef test_repeated_ready_events_own_one_classification_task():\n    scope = _bot_namespace()\n    bot = object.__new__(scope["DemandBot"])\n    bot.user, bot.chans, bot.mode, bot.display_id = "synthetic", {}, "dry", None\n    bot.post_direct = bot.post_community = bot.post_display = False\n    bot.log = lambda message: None\n    tasks = []\n\n    class Task:\n        def __init__(self, coroutine):\n            self.coroutine = coroutine\n        def done(self):\n            return False\n        def add_done_callback(self, callback):\n            self.callback = callback\n\n    def create_task(coroutine):\n        task = Task(coroutine)\n        tasks.append(task)\n        return task\n\n    bot.loop = types.SimpleNamespace(create_task=create_task)\n    try:\n        _run_coroutine(bot.on_ready())\n        _run_coroutine(bot.on_ready())\n        assert len(tasks) == 1\n        assert getattr(bot, "_classify_task", None) is tasks[0]\n    finally:\n        for task in tasks:\n            task.coroutine.close()\n\n\n@pytest.mark.parametrize("transport_name", ["ssh", "scoped-https"])\ndef test_permitted_transports_keep_nonrouting_configuration(transport, transport_name):\n    root, state = transport\n    state.update(copy.deepcopy(REVIEW["permitted_transport"][transport_name]))\n    proof = data_safety.require_private(root / "synthetic.json")\n    assert proof["repository"] == "example/demand-mining-config"\n\n\n@pytest.mark.parametrize("change", [False, True], ids=["healthy", "changed-before-push"])\ndef test_backup_uses_current_transport_proof_at_actual_launcher(tmp_path, monkeypatch, change):\n    spec = importlib.util.spec_from_file_location("_review15_backup", Path(data_safety.__file__).with_name("backup.py"))\n    backup = importlib.util.module_from_spec(spec)\n    spec.loader.exec_module(backup)\n    root = tmp_path / "companion"\n    root.mkdir()\n    (root / ".git").mkdir()\n    record = root / "record.json"\n    record.write_text(json.dumps(REVIEW["backup_record"]), encoding="utf-8")\n    state = {"config": "", "pushes": 0}\n    monkeypatch.setattr(data_safety, "_companion_proof", lambda directory: types.SimpleNamespace(\n        root=str(root), repositories=("example/demand-mining-config",), signature=state["config"]))\n\n    def child(argv, **kwargs):\n        args = argv[3:]\n        if args == ["rev-parse", "--show-toplevel"]:\n            output = str(root)\n        elif args[0] == "config":\n            output = state["config"]\n        elif args[:2] == ["remote", "get-url"]:\n            output = REVIEW["transport"][0]["url"]\n        elif args[0] in {"read-tree", "add", "diff", "commit", "push"}:\n            output = ""\n            if args[0] == "add" and change:\n                key, value = next(case for case in REVIEW["transport"] if case["name"] == "blocked-config-0")["config"][0]\n                state["config"] = key + "\\n" + value + "\\0"\n            if args[0] == "push":\n                state["pushes"] += 1\n                assert kwargs["env"]["GIT_OPTIONAL_LOCKS"] == "0"\n        else:\n            raise AssertionError("unexpected synthetic Git command")\n        return subprocess.CompletedProcess(argv, 0, stdout=output, stderr="")\n\n    monkeypatch.setattr(data_safety.subprocess, "run", child)\n    if change:\n        with pytest.raises((data_safety.DestinationError, ValueError)):\n            backup._backup_locked([record])\n        assert state["pushes"] == 0\n    else:\n        assert backup._backup_locked([record])["status"] == "confirmed"\n        assert state["pushes"] == 1\n\n\ndef test_git_push_without_an_admitted_proof_never_launches(tmp_path, monkeypatch):\n    calls = []\n    monkeypatch.setattr(data_safety.subprocess, "run", lambda *args, **kwargs: calls.append(args))\n    with pytest.raises(data_safety.DestinationError):\n        data_safety.git(tmp_path, "push", "origin", "HEAD")\n    assert calls == []\n\n\ndef test_unexpected_worker_exit_restarts_with_the_same_pending_batch():\n    scope = _bot_namespace()\n    bot = object.__new__(scope["DemandBot"])\n    pending = [{"message": REVIEW["worker"][0]}]\n    bot._pending_batch = pending\n    bot.is_closed = lambda: False\n    logs, tasks = [], []\n    bot.log = logs.append\n    old = types.SimpleNamespace(done=lambda: True, cancelled=lambda: False,\n                                exception=lambda: RuntimeError("synthetic worker termination"))\n    bot._classify_task = old\n\n    class NewTask:\n        def __init__(self, coroutine):\n            self.coroutine = coroutine\n        def add_done_callback(self, callback):\n            self.callback = callback\n        def done(self):\n            return False\n\n    def create_task(coroutine):\n        task = NewTask(coroutine)\n        tasks.append(task)\n        return task\n\n    bot.loop = types.SimpleNamespace(create_task=create_task)\n    try:\n        bot._classify_done(old)\n        assert len(tasks) == 1 and bot._classify_task is tasks[0]\n        assert bot._pending_batch is pending\n        assert bot.classification_status == "retrying"\n        assert logs\n    finally:\n        for task in tasks:\n            task.coroutine.close()\n', 'test_review18_repairs.py': '"""Inert regressions for complete private destinations and headline capacity."""\nfrom copy import deepcopy\nfrom contextlib import contextmanager\nimport datetime\nimport json\nimport os\nimport subprocess\nimport tempfile\nfrom unittest.mock import patch\nimport importlib.util\nfrom pathlib import Path\nimport types\nimport unittest\n\nROOT = Path(__file__).parents[3]\nSCRIPTS = ROOT / "skills/demand-mining/scripts"\n\n\ndef module(name, path):\n    spec = importlib.util.spec_from_file_location(name, path)\n    value = importlib.util.module_from_spec(spec)\n    spec.loader.exec_module(value)\n    return value\n\n\nCASES = module("_review18_fixture_generator", ROOT / "tools/make_fixtures.py").review18_cases()\nPRIOR = module("_review18_inert_support", Path(__file__).with_name("test_review17_repairs.py"))\n\n\n@contextmanager\ndef transport(case):\n    safety = module("_review18_data_safety", SCRIPTS / "data_safety.py")\n    with tempfile.TemporaryDirectory(prefix="demand-transport-") as temporary:\n        root = Path(temporary) / "companion"\n        root.mkdir()\n        profile = Path(temporary) / "profile"\n        profile.mkdir()\n        environment = {key: value for key, value in os.environ.items() if not key.upper().startswith("GIT_")}\n        environment.update(HOME=str(profile), USERPROFILE=str(profile),\n                           GIT_CONFIG_GLOBAL=os.devnull, GIT_CONFIG_NOSYSTEM="1")\n        with patch.dict(os.environ, environment, clear=True):\n            subprocess.run(["git", "-C", str(root), "init", "-q"], check=True, capture_output=True)\n            baseline = (root / ".git/config").read_bytes()\n            state = deepcopy(case)\n            receipt = profile / "visibility.json"\n            receipt.write_text(json.dumps({\n                "_refreshed": datetime.datetime.now(datetime.timezone.utc).isoformat(),\n                "example-owner/private-store": "PRIVATE", "example-owner/private-archive": "PRIVATE",\n                "example-owner/private-mirror": "PRIVATE", "example-owner/public-store": "PUBLIC",\n                **({state["unknown"]: "UNKNOWN"} if state.get("unknown") else {})}), encoding="utf-8")\n            calls, visibility = [], []\n            api = safety._guard_api()\n\n            def companion(directory):\n                (root / ".git/config").write_bytes(baseline)\n                entries = list(state["config"])\n                keys = {key for key, value in entries}\n                for name, urls in state["urls"].items():\n                    if "remote."+name+".url" not in keys:\n                        entries.append(("remote."+name+".url", urls[0]))\n                    if len(urls) > 1 and "remote."+name+".pushurl" not in keys:\n                        entries.append(("remote."+name+".pushurl", urls[-1]))\n                for key, value in entries:\n                    subprocess.run(["git", "-C", str(root), "config", "--add", key, value],\n                                   check=True, capture_output=True)\n                proof = api.prove_private_companion(directory, visibility_map=receipt)\n                visibility[:] = proof.repositories\n                return proof\n\n            safety._companion_proof = companion\n            yield safety, root, state, calls, visibility\n\n\nclass DestinationCoverageTests(unittest.TestCase):\n    def test_all_configured_and_selected_destinations_require_private_proof(self):\n        for case in CASES["transport"]:\n            with self.subTest(case=case["name"]), transport(case) as (safety, root, state, calls, visibility):\n                if case["accept"]:\n                    proof = safety._transport_proof(root)\n                    self.assertEqual(proof["repository"], "example-owner/private-store")\n                    expected = set(case.get("repositories", ["example-owner/private-store"]))\n                    self.assertEqual(set(proof["repositories"]), expected)\n                    self.assertEqual(set(visibility), expected)\n                else:\n                    with self.assertRaises(safety.DestinationError):\n                        safety._transport_proof(root)\n\n    def test_secondary_destination_change_invalidates_the_transport_binding(self):\n        case = next(case for case in CASES["transport"] if case["name"] == "private-secondary")\n        with transport(case) as (safety, root, state, calls, visibility):\n            before = safety._transport_proof(root)\n            state["config"] = [(key, value) for key, value in state["config"]\n                               if key != "remote.archive.url"]\n            state["config"].append(("remote.archive.url", "https://github.com/example-owner/private-mirror.git"))\n            after = safety.require_private_push(root, before["repository"])\n            self.assertNotEqual(after["sha256"], before["sha256"])\n            self.assertIn("example-owner/private-mirror", visibility)\n\n\nclass HeadlineCapacityTests(unittest.TestCase):\n    def product(self):\n        support = PRIOR.BatchConservationTests()\n        support.setUp()\n        support.p.cfg["push"]["max_per_day"] = 1\n        return support\n\n    def candidates(self, kano):\n        noise, useful = deepcopy(CASES["noise"]), deepcopy(CASES["useful"])\n        noise["kano"] = kano\n        return [noise, useful]\n\n    def test_cut_cannot_consume_capacity_or_proposed_push_bookkeeping(self):\n        for kano in CASES["cut_kano"]:\n            for reverse in (False, True):\n                with self.subTest(kano=kano, reverse=reverse):\n                    support = self.product()\n                    candidates = self.candidates(kano)\n                    plan = support.prepare(list(reversed(candidates)) if reverse else candidates)\n                    cards = {c["title"]: c for c in plan["cards"]}\n                    noise, useful = candidates\n                    self.assertEqual(cards[noise["title"]]["tier"], "cut")\n                    self.assertGreater(cards[noise["title"]]["final_score"], cards[useful["title"]]["final_score"])\n                    self.assertEqual(plan["result"]["proposed_push"], [useful["title"]])\n                    self.assertIn(useful["title"], plan["headlines"])\n                    self.assertNotIn(noise["title"], plan["headlines"])\n                    self.assertEqual({row["card"]["title"]: row["pushed"] for row in plan["mutations"]},\n                                     {noise["title"]: False, useful["title"]: True})\n\n    def test_finalizer_receipt_push_counts_and_replay_match_rendered_selection(self):\n        for kano in CASES["cut_kano"]:\n            with self.subTest(kano=kano):\n                support = self.product()\n                candidates = self.candidates(kano)\n\n                def invoke():\n                    return support.p.final.finalize(candidates, support.p.cfg, support.ledger, False,\n                        "synthetic-review18", "synthetic/archive", identity=support.identity,\n                        attempt_id="synthetic-attempt")\n\n                first = invoke()\n                self.assertEqual(first["status"], "complete")\n                self.assertEqual(first["pushed"], [candidates[1]["title"]])\n                self.assertEqual(len(support.p.sends), 1)\n                self.assertIn(candidates[1]["title"], support.p.sends[0])\n                self.assertNotIn(candidates[0]["title"], support.p.sends[0])\n                prefix = support.p.dd.EXT\n                for candidate, count in zip(candidates, (0, 1)):\n                    self.assertEqual(support.ledger.rows[candidate["canonical_key"]]["ext"][prefix + "push_count"], count)\n                before = deepcopy((support.ledger.rows, support.ledger.writes,\n                                   support.ledger.watermarks, support.p.sends))\n                self.assertEqual(invoke()["pushed"], first["pushed"])\n                self.assertEqual((support.ledger.rows, support.ledger.writes,\n                                  support.ledger.watermarks, support.p.sends), before)\n\n    def test_tier0_retains_priority_below_the_score_floor(self):\n        support = self.product()\n        urgent = deepcopy(CASES["urgent"])\n        plan = support.prepare([deepcopy(CASES["useful"]), urgent])\n        card = next(c for c in plan["cards"] if c["title"] == urgent["title"])\n        self.assertEqual(card["tier"], "tier0")\n        self.assertLess(card["final_score"], support.p.cfg["scoring"]["min_score_to_push"])\n        self.assertEqual(plan["result"]["proposed_push"], [urgent["title"]])\n        self.assertIn(urgent["title"], plan["headlines"])\n\n    def test_all_cut_day_has_no_proposed_or_planned_push(self):\n        support = self.product()\n        noise = self.candidates("indifferent")[0]\n        plan = support.prepare([noise])\n        self.assertEqual(plan["result"]["proposed_push"], [])\n        self.assertTrue(all(not row["pushed"] for row in plan["mutations"]))\n        self.assertNotIn(noise["title"], plan["headlines"])\n\n\nif __name__ == "__main__":\n    unittest.main()\n', 'test_ledger_pipeline.py': '"""T5, schedule-reminder base round-trip (real subprocess) + full offline pipeline.\n\nThe ledger tests use the REAL reminder.py contract (subprocess, temp DB), if it is not present\nthey skip (the offline pipeline tests still run). Asserts: canonical_key UPSERT is idempotent\n(no double item across re-runs), ext.x_demand_mining_* round-trips (MUST-PRESERVE), source\nisolation, and that PII in the raw input never reaches the pushed/archived card.\n"""\nimport os\nimport datetime\nimport hashlib\nimport json\nfrom pathlib import Path\nimport subprocess\nimport sys\n\nimport pytest\n\nfrom lib import load_config\nimport dedup as dd\nimport run as R\nimport push_card\n\nCFG = load_config()\nREMINDER = Path.home() / ".claude/skills/schedule-reminder/scripts/reminder.py"\nhave_base = REMINDER.is_file()\nledger_only = pytest.mark.skipif(not have_base, reason="schedule-reminder base not installed")\n\n\n@pytest.fixture\ndef native_ledger(tmp_path, monkeypatch):\n    """Use real Git, the real reminder CLI and a synthetic local visibility receipt."""\n    case = json.loads((Path(__file__).parent / "fixtures/repair_cases.json").read_text())["native_ledger"]\n    profile = tmp_path / "profile"\n    receipt_dir = profile / ".pii-guard"\n    receipt_dir.mkdir(parents=True)\n    repository = case["repository"]\n    (receipt_dir / "visibility.json").write_text(json.dumps({\n        repository: "PRIVATE", "_refreshed": datetime.datetime.now(datetime.timezone.utc).isoformat(),\n        "_verified": {repository: {"v": "PRIVATE"}}}), encoding="utf-8")\n    monkeypatch.setenv("USERPROFILE", str(profile))\n    monkeypatch.setenv("HOME", str(profile))\n    monkeypatch.setenv("GIT_CONFIG_NOSYSTEM", "1")\n    monkeypatch.setenv("GIT_CONFIG_GLOBAL", os.devnull)\n    companion = tmp_path / "companion"\n    companion.mkdir()\n    for args in (("init", "--quiet"), ("remote", "add", "origin", case["origin"])):\n        subprocess.run(["git", "-C", str(companion), *args], check=True, capture_output=True)\n    subprocess.run(["git", "-C", str(companion), "-c", "user.name=Synthetic Fixture",\n                    "-c", "user.email=user1@example.com", "commit", "--allow-empty",\n                    "-m", "Initialize synthetic companion"], check=True, capture_output=True)\n    sends = []\n\n    def confirm(message, dry_run=False):\n        sends.append(message)\n        return True, {"status": "confirmed", "message_id": case["receipt_id"],\n                      "identity": push_card._DELIVERY_IDENTITY.get(),\n                      "content_sha256": hashlib.sha256(message.encode("utf-8")).hexdigest()}\n\n    monkeypatch.setattr(push_card, "deliver", confirm)\n    cfg = {**CFG, **case["config"]}\n    from native_fixture import native_reminder\n    launcher = native_reminder(tmp_path, REMINDER)\n    client = dd.LedgerClient(cmd=[sys.executable, str(launcher)],\n                             db_path=str(companion / "t.db"), product_id=cfg["product_id"])\n    # The shared store is initialized explicitly by its own CLI, before Demand attaches.\n    subprocess.run([sys.executable, str(launcher), "--db", client.db_path, "init"],\n                   check=True, capture_output=True)\n    client.init()\n    return client, cfg, str(companion / "pool"), sends\n\n\ndef _cand(title, job, track, sources, pii_author="user-1"):\n    return {\n        "title": title, "summary": "", "inferred_job": job, "track": track,\n        "evidence": [{"channel": s, "origin_type": "internal" if s == "discord" else "external",\n                      "redacted_snippet": "the export keeps timing out", "ts": "2026-06-25T11:00:00Z"}\n                     for s in sources],\n        "authors": [{"user_id": pii_author, "urgency": "need", "segment": "pro"},\n                    {"user_id": "user-2", "urgency": "should", "segment": "team"}],\n        "independent_source_count": len(sources),\n        "reach": 4, "impact_label": "high", "effort_weeks": 2,\n        "has_internal_explicit": True, "internal_mentions": 4,\n        "importance": 9, "satisfaction": 2,\n        "user_business_value": 8, "time_criticality": 8, "risk_reduction": 3, "job_size": 5,\n        "kano": "performance", "why": "users churn on slow export",\n        "recommendation": "stream the export incrementally", "new_mentions": 2,\n    }\n\n\n# ---------------------------------------------------------------- offline pipeline (no base)\ndef test_offline_pipeline_runs_and_redacts():\n    cand = _cand("faster csv export", "reliably export my data", "integrations",\n                 ["discord", "reddit"])\n    # inject PII into a visible field; the pipeline must scrub it before push/archive\n    cand["title"] = "faster csv export ping bob@acme.io"\n    res = R.process([cand], CFG, ledger=None, dry_run=True)\n    assert res["built"] == 1\n    assert res["empty_day"] is False\n    # the digest markdown must not contain the raw email (redact-on-ingest)\n    assert "bob@acme.io" not in res["digest_markdown"]\n\n\ndef test_offline_empty_day_low_quality():\n    weak = _cand("minor tweak", "small thing", "other", ["discord"])\n    weak["reach"] = 1; weak["impact_label"] = "minimal"; weak["importance"] = 2\n    weak["satisfaction"] = 9; weak["kano"] = "indifferent"; weak["independent_source_count"] = 1\n    res = R.process([weak], CFG, ledger=None, dry_run=True)\n    assert res["empty_day"] is True\n\n\n# ---------------------------------------------------------------- base round-trip (real subprocess)\n@ledger_only\ndef test_ledger_roundtrip_idempotent(native_ledger):\n    lc, cfg, archive, sends = native_ledger\n    cand = _cand("dark mode", "reduce eye strain at night", "ui-ux", ["discord", "reddit"])\n\n    first = R.process([cand], cfg, ledger=lc, dry_run=False, archive_dir=archive)\n    assert first["status"] == "complete"\n    rows1 = [r for r in lc.list_active() if r.get("source") == "demand-mining"]\n    demands1 = [r for r in rows1 if dd._row_key(r).startswith("demand-mining:")\n                and "watermark" not in dd._row_key(r) and "digest" not in dd._row_key(r)]\n\n    # re-run identical input: canonical_key UPSERT must NOT create a second demand item\n    replay = R.process([cand], cfg, ledger=lc, dry_run=False, archive_dir=archive)\n    assert replay["status"] == "complete"\n    rows2 = [r for r in lc.list_active() if r.get("source") == "demand-mining"]\n    demands2 = [r for r in rows2 if dd._row_key(r).startswith("demand-mining:")\n                and "watermark" not in dd._row_key(r) and "digest" not in dd._row_key(r)]\n    assert len(demands2) == len(demands1) == 1   # idempotent: no double立项\n    assert len(sends) == 1\n    assert lc.get_watermark() == first["identity"]["source_window"]["end"]\n\n\n@ledger_only\ndef test_ledger_ext_namespace_preserved(native_ledger):\n    lc, cfg, archive, _ = native_ledger\n    cand = _cand("slack alerts", "get notified in slack", "integrations", ["discord", "reddit"])\n    result = R.process([cand], cfg, ledger=lc, dry_run=False, archive_dir=archive)\n    assert result["status"] == "complete"\n    rows = [r for r in lc.list_active()\n            if dd._row_key(r).startswith("demand-mining:") and "watermark" not in dd._row_key(r)\n            and "digest" not in dd._row_key(r)]\n    assert rows, "demand item not written"\n    ext = dd._row_ext(rows[0])\n    # MUST-PRESERVE: our namespace survives the round-trip with the demand-only fields\n    assert ext.get(dd.EXT + "intensity") is not None\n    assert ext.get(dd.EXT + "distinct_author_count") == 2\n    # no raw user_id ever stored (HMAC pseudonyms only)\n    assert all("user-1" not in str(a) for a in ext.get(dd.EXT + "authors", []))\n\n\n@ledger_only\ndef test_ledger_source_isolation(native_ledger):\n    lc, cfg, archive, _ = native_ledger\n    # write a foreign-source item directly; our list_active(source=demand-mining) must not see it\n    lc._run("add", ["--title", "foreign", "--kind", "task", "--source", "other-skill",\n                    "--idempotency-key", "other-skill:x"])\n    cand = _cand("export", "export data", "integrations", ["discord", "reddit"])\n    result = R.process([cand], cfg, ledger=lc, dry_run=False, archive_dir=archive)\n    assert result["status"] == "complete"\n    keys = [dd._row_key(r) for r in lc.list_active()]\n    assert all(not k.startswith("other-skill:") for k in keys)\n\n\n# ---------------------------------------------------------------- T6 batch-5: entities PII leak\ndef test_raw_pii_in_entities_scrubbed_from_canonical_key():\n    """Defense-in-depth (T6): even if the upstream slips raw PII into the proposed `entities`, it must\n    NOT survive into canonical_key, which becomes the schedule-reminder idempotency_key persisted\n    LONG-TERM in the need pool. build_card redacts only text fields/evidence/authors; the entities ->\n    canonical_key path was trusted verbatim, leaking an email/handle into the pool key. has_pii over\n    the canonical_key must be False, while a clean entity list stays byte-identical (no over-scrub)."""\n    from redact import has_pii\n    from lib import canonical_key as _ck\n    dirty = {"title": "please add export", "summary": "we need export",\n             "inferred_job": "export data",\n             "entities": ["export", "data", "alice@example.com", "@johndoe"],\n             "evidence": [{"channel": "discord", "origin_type": "internal",\n                           "redacted_snippet": "add export pls", "ts": "2026-06-25T10:00:00Z"}],\n             "authors": [{"author_hash": "u_x", "urgency": "need", "segment": "pro"}],\n             "reach": 3, "impact_label": "high", "independent_source_count": 1,\n             "has_internal_explicit": True, "importance": 8, "satisfaction": 2,\n             "user_business_value": 5, "time_criticality": 3, "risk_reduction": 2, "job_size": 3}\n    card = R.build_card(dirty, CFG, "r1")\n    assert not has_pii(card["canonical_key"])           # no raw email/handle in the persisted key\n    assert "@" not in card["canonical_key"] and "alice" not in card["canonical_key"]\n    # guard: a clean entity list is byte-identical to the direct canonical_key (no over-scrub)\n    clean = dict(dirty); clean["entities"] = ["export", "data", "schedule"]\n    ck_clean = R.build_card(clean, CFG, "r1")["canonical_key"]\n    assert ck_clean == _ck(["export", "data", "schedule"], "other")\n', 'test_review19_repairs.py': '"""Full-module Demand19 regressions with generated inputs and synthetic effects."""\nimport builtins\nimport copy\nimport io\nimport json\nimport os\nfrom pathlib import Path, PurePosixPath\nimport posixpath\nimport stat\nimport sys\nimport types\nimport unittest\n\nROOT = Path(__file__).parents[3]\nSCRIPTS = ROOT / "skills/demand-mining/scripts"\n\n\ndef source_bytes(path):\n    for node in reversed((path, *path.parents)):\n        info = os.lstat(node)\n        if stat.S_ISLNK(info.st_mode) or getattr(info, "st_file_attributes", 0) & 1024:\n            raise AssertionError("unsafe source topology")\n        if node != path and not stat.S_ISDIR(info.st_mode):\n            raise AssertionError("unsafe source ancestor")\n        if node == path and (not stat.S_ISREG(info.st_mode) or info.st_nlink != 1):\n            raise AssertionError("unsafe source leaf")\n    return path.read_bytes()\n\n\ngenerator = types.ModuleType("demand19_generated")\ngenerator.__file__ = str(ROOT / "tools/make_fixtures.py")\nexec(compile(source_bytes(Path(generator.__file__)), generator.__file__, "exec"), generator.__dict__)\nCASES = generator.review19_cases()\n\n\nclass ControlledStop(BaseException):\n    pass\n\n\nclass Harness:\n    def __init__(self, behavior="normal"):\n        self.behavior = behavior\n        self.visibility = "PRIVATE"\n        self.files, self.opens, self.writes, self.children, self.proofs = {}, [], [], [], []\n        self.modules = {}\n        self.root = CASES["private_root"]\n        self.dirs = {self.root, self.root + "/logs", self.root + "/.git"}\n        self.sys = types.SimpleNamespace(**vars(sys))\n        self.sys.stdout, self.sys.stderr = io.StringIO(), io.StringIO()\n        self.original_streams = self.sys.stdout, self.sys.stderr\n        self.args = types.SimpleNamespace(\n            config_dir=self.root, python="synthetic-python", mode="dry", interval=90,\n            display_interval=300, log_dir=self.root + "/logs", min_backoff=1.0,\n            max_backoff=4.0, dry_run=True, run_seconds=0,\n            log_file=self.root + "/logs/direct.log")\n        self.files[self.root + "/priority.json"] = json.dumps(CASES["config"]).encode()\n        self.files[self.root + "/registry.json"] = json.dumps(CASES["registry"]).encode()\n        self.files[self.root + "/synthetic-token.txt"] = CASES["synthetic_token"].encode()\n        h = self\n\n        class MemoryPath:\n            def __init__(self, value):\n                self.value = str(value).replace("\\\\", "/").rstrip("/") or "/"\n            def __str__(self):\n                return self.value\n            def __fspath__(self):\n                return self.value\n            def __eq__(self, other):\n                return self.value == str(other)\n            def __hash__(self):\n                return hash(self.value)\n            def __truediv__(self, other):\n                return MemoryPath(self.value.rstrip("/") + "/" + str(other))\n            @property\n            def parent(self):\n                return MemoryPath(str(PurePosixPath(self.value).parent))\n            @property\n            def parents(self):\n                return [MemoryPath(str(p)) for p in PurePosixPath(self.value).parents]\n            @property\n            def name(self):\n                return PurePosixPath(self.value).name\n            @property\n            def parts(self):\n                return PurePosixPath(self.value).parts\n            def lstat(self):\n                if not self.exists():\n                    raise FileNotFoundError(self.value)\n                return types.SimpleNamespace(st_mode=stat.S_IFDIR if self.is_dir() else stat.S_IFREG,\n                                             st_nlink=1, st_file_attributes=0)\n            def expanduser(self):\n                return self\n            def resolve(self):\n                return self\n            def absolute(self):\n                return self\n            def is_relative_to(self, other):\n                return self.value == str(other) or self.value.startswith(str(other).rstrip("/") + "/")\n            def is_dir(self):\n                return self.value in h.dirs\n            def is_file(self):\n                return self.value in h.files\n            def exists(self):\n                return self.is_dir() or self.is_file()\n            def mkdir(self, **kwargs):\n                h.dirs.add(self.value)\n            def read_text(self, encoding="utf-8"):\n                return h.files[self.value].decode(encoding)\n            def read_bytes(self):\n                return h.files[self.value]\n\n        class MemoryFile:\n            def __init__(self, path, mode):\n                self.name, self.mode, self.closed = str(path), mode, False\n                h.opens.append((self.name, h.visibility))\n                h.files.setdefault(self.name, b"")\n            def write(self, value):\n                if h.behavior == "write-error":\n                    raise OSError("synthetic append failed")\n                self.raw_write(value)\n                return len(value)\n            def raw_write(self, value):\n                if self.closed:\n                    raise ValueError("closed synthetic stream")\n                data = value.encode("utf-8") if isinstance(value, str) else value\n                h.files[self.name] = h.files.get(self.name, b"") + data\n                h.writes.append((self.name, data, h.visibility))\n            def flush(self):\n                pass\n            def close(self):\n                self.closed = True\n            def fileno(self):\n                return 77\n            def __enter__(self):\n                return self\n            def __exit__(self, *args):\n                self.close()\n\n        def memory_open(path, mode="r", **kwargs):\n            if mode not in ("a", "ab"):\n                raise AssertionError("unexpected product open mode")\n            if h.behavior == "open-error":\n                raise OSError("synthetic open failed")\n            return MemoryFile(path, mode)\n\n        class Parser:\n            def __init__(self, **kwargs):\n                pass\n            def add_argument(self, *args, **kwargs):\n                pass\n            def parse_args(self):\n                return h.args\n\n        def sleep(seconds):\n            if h.behavior == "revoke-before-restart" and len(h.children) == 1:\n                h.visibility = "PUBLIC"\n                return\n            raise ControlledStop()\n\n        class Pipe:\n            def __init__(self):\n                self.index = 0\n                self.closed = False\n            def read(self, size):\n                assert 0 < size <= 65536\n                if self.index == 1 and h.behavior == "revoke-during-child":\n                    h.visibility = "PUBLIC"\n                chunks = [x.encode() for x in CASES["child_chunks"]] + [bytes.fromhex(CASES["binary_tail_hex"])]\n                if self.index >= len(chunks):\n                    if h.behavior == "revoke-after-child":\n                        h.visibility = "PUBLIC"\n                    return b""\n                chunk = chunks[self.index]\n                self.index += 1\n                return chunk\n            def close(self):\n                self.closed = True\n\n        class Child:\n            def __init__(self):\n                self.stdout, self.returncode = Pipe(), None\n                self.terminated, self.killed = False, False\n            def poll(self):\n                return self.returncode\n            def wait(self, timeout=None):\n                self.returncode = 0 if self.returncode is None else self.returncode\n                return self.returncode\n            def terminate(self):\n                self.terminated, self.returncode = True, -15\n            def kill(self):\n                self.killed, self.returncode = True, -9\n\n        def popen(argv, **kwargs):\n            assert kwargs["stdout"] == "SYNTHETIC_PIPE"\n            assert kwargs["stderr"] == "SYNTHETIC_STDOUT"\n            if h.behavior == "launch-error":\n                raise OSError(CASES["startup_error"])\n            child = Child()\n            h.children.append(child)\n            if len(h.children) > 1:\n                raise ControlledStop()\n            return child\n\n        def call(argv, **kwargs):\n            if h.behavior == "launch-error":\n                raise OSError(CASES["startup_error"])\n            child = Child()\n            h.children.append(child)\n            if len(h.children) > 1:\n                raise ControlledStop()\n            while True:\n                chunk = child.stdout.read(65536)\n                if not chunk:\n                    break\n                # Models inherited OS handles, which bypass Python stream.write.\n                kwargs["stdout"].raw_write(chunk)\n            return child.wait()\n\n        class Client:\n            def __init__(self, **kwargs):\n                self.loop = types.SimpleNamespace()\n            def run(self, token, **kwargs):\n                if h.behavior == "direct-startup-error":\n                    raise RuntimeError(CASES["startup_error"])\n                self.log(CASES["log_messages"][0])\n                if h.behavior == "direct-revoke":\n                    h.visibility = "PUBLIC"\n                self.log(CASES["log_messages"][1])\n\n        self.Path = MemoryPath\n        self.open = memory_open\n        self.os = types.SimpleNamespace(\n            environ={"DEMAND_MINING_CONFIG": self.root}, name="synthetic",\n            path=types.SimpleNamespace(join=posixpath.join, dirname=posixpath.dirname,\n                abspath=lambda value: value, isfile=lambda value: False, isabs=posixpath.isabs,\n                lexists=lambda value: MemoryPath(value).exists()),\n            makedirs=lambda path, **kwargs: self.dirs.add(str(path)))\n        self.time = types.SimpleNamespace(time=lambda: 1, strftime=lambda fmt: "2026-01-15", sleep=sleep)\n        self.subprocess = types.SimpleNamespace(Popen=popen, call=call, PIPE="SYNTHETIC_PIPE",\n            STDOUT="SYNTHETIC_STDOUT", TimeoutExpired=TimeoutError)\n        self.effects = {\n            "os": self.os, "sys": self.sys, "time": self.time,\n            "pathlib": types.SimpleNamespace(Path=MemoryPath),\n            "argparse": types.SimpleNamespace(ArgumentParser=Parser),\n            "subprocess": self.subprocess,\n            "zoneinfo": types.SimpleNamespace(ZoneInfo=lambda zone: __import__("datetime").timezone.utc),\n            "discord": types.SimpleNamespace(Client=Client,\n                Intents=types.SimpleNamespace(default=lambda: types.SimpleNamespace())),\n            "llmcall": types.SimpleNamespace(call=self.forbidden),\n            "redact": types.SimpleNamespace(redact=lambda value: {"redacted": value},\n                safe_data=copy.deepcopy, safe_text=lambda value: value, has_pii=lambda value: False,\n                pseudonymize=lambda value: "synthetic-author", PrivacyReviewRequired=RuntimeError,\n                ensure_stable_salt=lambda: None),\n            "demand_pool": types.SimpleNamespace(pool_path=lambda config: self.root + "/pool.jsonl"),\n            "dedup": types.SimpleNamespace(), "verify_gate": types.SimpleNamespace(gate_batch=self.forbidden),\n            "push_card": types.SimpleNamespace(), "digest": types.SimpleNamespace(),\n            "finalize": types.SimpleNamespace(logical_identity=lambda cfg: {"synthetic": True}),\n        }\n\n    @staticmethod\n    def forbidden(*args, **kwargs):\n        raise AssertionError("external effect forbidden")\n\n    def importer(self, name, globals=None, locals=None, fromlist=(), level=0):\n        if name in self.modules:\n            return self.modules[name]\n        if name in self.effects:\n            return self.effects[name]\n        allowed = {"__future__", "contextlib", "json", "hashlib", "importlib.util", "stat",\n                   "urllib.parse", "re", "tempfile", "datetime", "asyncio", "math", "traceback"}\n        if name in allowed:\n            return builtins.__import__(name, globals, locals, fromlist, level)\n        raise AssertionError("unadmitted product import: " + name)\n\n    def load(self, name, path=None):\n        path = path or SCRIPTS / (name + ".py")\n        module = types.ModuleType(name)\n        module.__file__ = str(path)\n        module.__dict__["__builtins__"] = {\n            **vars(builtins), "__import__": self.importer, "open": self.open}\n        self.modules[name] = module\n        exec(compile(source_bytes(path), str(path), "exec"), module.__dict__)\n        if name == "data_safety":\n            module.git = self.git\n            module._companion_proof = self.companion\n        return module\n\n    def git(self, root, *args, **kwargs):\n        if args == ("rev-parse", "--show-toplevel"):\n            text = self.root\n        elif args == ("config", "--null", "--list"):\n            text = "remote.origin.url\\n" + CASES["private_remote"] + "\\0"\n        elif args[:2] == ("remote", "get-url"):\n            text = CASES["private_remote"]\n        else:\n            raise AssertionError("unadmitted synthetic Git query")\n        return types.SimpleNamespace(stdout=text)\n\n    def companion(self, root):\n        repository = CASES["private_remote"].removeprefix("https://github.com/").removesuffix(".git")\n        if self.visible(repository) != "PRIVATE":\n            raise self.modules["data_safety"].DestinationError("synthetic repository visibility is not PRIVATE")\n        return types.SimpleNamespace(root=self.Path(self.root), repositories=(repository,),\n                                     signature="synthetic-current-transport")\n\n    def visible(self, repository):\n        self.proofs.append((repository, self.visibility))\n        return self.visibility\n\n    def scoring(self):\n        lib = self.load("lib")\n        score = self.load("score")\n        run = self.load("run")\n        return lib, score, run\n\n    def logging(self):\n        self.load("lib")\n        self.load("data_safety")\n        try:\n            os.lstat(SCRIPTS / "private_log.py")\n        except FileNotFoundError:\n            pass\n        else:\n            self.load("private_log")\n        self.load("score")\n        return self.load("daemon_supervisor"), self.load("demand_bot")\n\n    def invoke(self, function):\n        try:\n            function()\n        except ControlledStop:\n            return "controlled-stop"\n        except (SystemExit, self.modules["data_safety"].DestinationError):\n            return "stopped"\n        return "returned"\n\n\nclass ScoringPathTests(unittest.TestCase):\n    def test_generated_weights_and_effort_use_one_production_path(self):\n        h = Harness()\n        lib, score, run = h.scoring()\n        for case in CASES["scores"]:\n            with self.subTest(case=case["name"]):\n                cfg = copy.deepcopy(lib.DEFAULT_CONFIG)\n                cfg["scoring"]["rice_weights"].update(case["weights"])\n                proposal = copy.deepcopy(CASES["proposal"])\n                proposal["effort_weeks"] = case["effort"]\n                for key in ("independent_source_count", "has_internal_explicit", "internal_mentions"):\n                    if case.get("evidence_mode") == "missing":\n                        proposal.pop(key, None)\n                    elif case.get("evidence_mode") == "null":\n                        proposal[key] = None\n                    elif case.get("evidence_mode") == "zero":\n                        proposal[key] = 0\n                before = copy.deepcopy((proposal, cfg))\n                actual = score.score_demand(proposal, cfg)["final_score"]\n                self.assertAlmostEqual(actual, case["expected"], places=4)\n                self.assertEqual(run.build_card(proposal, cfg, "synthetic-run19")["final_score"], actual)\n                self.assertEqual(score._final_map([proposal], None, cfg)[proposal["id"]], actual)\n                self.assertEqual(score._final_map([proposal], cfg["scoring"]["rice_weights"], cfg)[proposal["id"]], actual)\n                self.assertEqual((proposal, cfg), before)\n\n    def test_original_score_regression_functions_on_full_modules(self):\n        h = Harness()\n        h.scoring()\n        old = h.load("old_score_tests", ROOT / "skills/demand-mining/tests/test_score.py")\n        selected = [value for name, value in vars(old).items() if name.startswith("test_") and callable(value)]\n        self.assertEqual(len(selected), 17)\n        for method in selected:\n            with self.subTest(original=method.__name__):\n                method()\n\n\nclass CurrentLogAdmissionTests(unittest.TestCase):\n    def test_supervisor_preserves_all_private_child_bytes_and_uses_pipe(self):\n        h = Harness()\n        supervisor, _ = h.logging()\n        self.assertEqual(h.invoke(supervisor.main), "controlled-stop")\n        expected = b"".join(x.encode() for x in CASES["child_chunks"]) + bytes.fromhex(CASES["binary_tail_hex"])\n        self.assertEqual(h.files[h.root + "/logs/daemon-2026-01-15.log"], expected)\n        self.assertGreaterEqual(len(h.proofs), len(h.writes))\n        self.assertTrue(all(state == "PRIVATE" for _, _, state in h.writes))\n        self.assertIs(h.children[0].stdout.closed, True)\n\n    def test_supervisor_revocation_during_output_stops_child_without_unsafe_append(self):\n        h = Harness("revoke-during-child")\n        supervisor, _ = h.logging()\n        self.assertEqual(h.invoke(supervisor.main), "stopped")\n        self.assertTrue(h.children[0].terminated or h.children[0].killed)\n        self.assertEqual(len(h.children), 1)\n        self.assertTrue(all(state == "PRIVATE" for _, _, state in h.writes))\n        self.assertEqual(h.files[h.root + "/logs/daemon-2026-01-15.log"], CASES["child_chunks"][0].encode())\n\n    def test_supervisor_revocation_after_exit_and_before_restart_is_current(self):\n        for behavior in ("revoke-after-child", "revoke-before-restart"):\n            with self.subTest(behavior=behavior):\n                h = Harness(behavior)\n                supervisor, _ = h.logging()\n                self.assertEqual(h.invoke(supervisor.main), "stopped")\n                self.assertEqual(len(h.children), 1)\n                self.assertTrue(all(state == "PRIVATE" for _, _, state in h.writes))\n                self.assertTrue(all(state == "PRIVATE" for _, state in h.opens))\n\n    def test_supervisor_launch_exception_is_retained_in_private_log(self):\n        h = Harness("launch-error")\n        supervisor, _ = h.logging()\n        self.assertEqual(h.invoke(supervisor.main), "controlled-stop")\n        text = h.files[h.root + "/logs/supervisor.log"].decode()\n        self.assertIn(CASES["startup_error"], text)\n        self.assertIn("launch failed", text)\n        self.assertIn("restarting", text)\n\n    def test_direct_daemon_revalidates_each_write_and_restores_streams(self):\n        h = Harness("direct-revoke")\n        _, bot = h.logging()\n        self.assertEqual(h.invoke(bot.main), "stopped")\n        text = h.files[h.args.log_file].decode()\n        self.assertIn(CASES["log_messages"][0], text)\n        self.assertNotIn(CASES["log_messages"][1], text)\n        self.assertTrue(all(state == "PRIVATE" for _, _, state in h.writes))\n        self.assertEqual((h.sys.stdout, h.sys.stderr), h.original_streams)\n\n    def test_direct_private_success_and_startup_failure_keep_log_records(self):\n        for behavior in ("normal", "direct-startup-error"):\n            with self.subTest(behavior=behavior):\n                h = Harness(behavior)\n                _, bot = h.logging()\n                if behavior == "normal":\n                    self.assertEqual(bot.main(), 0)\n                    text = h.files[h.args.log_file].decode()\n                    self.assertTrue(all(message in text for message in CASES["log_messages"]))\n                else:\n                    with self.assertRaisesRegex(RuntimeError, CASES["startup_error"]):\n                        bot.main()\n                    text = h.files[h.args.log_file].decode()\n                    self.assertIn(CASES["startup_error"], text)\n                    self.assertIn("Traceback", text)\n                self.assertEqual((h.sys.stdout, h.sys.stderr), h.original_streams)\n\n    def test_private_log_io_failure_stops_without_silent_success(self):\n        for behavior in ("open-error", "write-error"):\n            with self.subTest(behavior=behavior):\n                h = Harness(behavior)\n                _, bot = h.logging()\n                self.assertEqual(h.invoke(bot.main), "stopped")\n                self.assertEqual((h.sys.stdout, h.sys.stderr), h.original_streams)\n                self.assertFalse(h.writes)\n\n\nif __name__ == "__main__":\n    unittest.main()\n'}

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--out", type=Path, help="export all generated files into this directory")
    args = ap.parse_args()
    test_out = args.out if args.out is not None else Path(__file__).resolve().parents[1] / "skills/demand-mining/tests"
    args.out = args.out if args.out is not None else test_out / "fixtures"
    args.out.mkdir(parents=True, exist_ok=True)
    (args.out / "repair_cases.json").write_text(
        json.dumps(fixtures(), indent=2, sort_keys=True) + "\n", encoding="utf-8")
    (args.out / "review21_cases.json").write_text(
        json.dumps(review21_cases(), indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    (args.out / "review22_cases.json").write_text(
        json.dumps(review22_cases(), indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    (test_out / "test_review22_repairs.py").write_text(review22_test_source(), encoding="utf-8")
    (args.out / "review23_cases.json").write_text(
        json.dumps(review23_cases(), indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    (test_out / "test_review23_repairs.py").write_text(review23_test_source(), encoding="utf-8")
    (args.out / "review24_cases.json").write_text(
        json.dumps(review24_cases(), indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    (test_out / "test_review24_repairs.py").write_text(review24_test_source(), encoding="utf-8")
    (args.out / "review25_cases.json").write_text(
        json.dumps(review25_cases(), indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    (test_out / "test_review25_repairs.py").write_text(review25_test_source(), encoding="utf-8")
    (test_out / "test_storage_boundary.py").write_text(storage_boundary_test_source(), encoding="utf-8")
    for name, source in storage_updated_test_sources().items():
        (test_out / name).write_text(source, encoding="utf-8")


if __name__ == "__main__":
    main()
